COMMENT ON TABLE "meta"."unit_dimension" IS 'The dimensionality of a unit as exponents of base dimensions.';
COMMENT ON COLUMN "meta"."unit_dimension"."unit" IS 'The unit.';
COMMENT ON COLUMN "meta"."unit_dimension"."dimension" IS 'A base dimension: mass, length, time, temperature, substance, ...';
COMMENT ON COLUMN "meta"."unit_dimension"."exponent" IS 'Its exponent.';

CREATE TABLE "meta"."quantity_type" (
    "id" uuid NOT NULL,
    "name" text NOT NULL,
    "module" text NOT NULL,
    "unit" text NOT NULL,
    "scale" text NOT NULL,
    "production" text,
    "pg_type" text NOT NULL,
    "doc" text NOT NULL,
    CONSTRAINT "quantity_type__pk" PRIMARY KEY ("id"),
    CONSTRAINT "quantity_type__uq__name" UNIQUE ("name"),
    CONSTRAINT "quantity_type__ck__scale" CHECK ("scale" IN ('absolute', 'difference', 'ratio', 'dimensionless', 'count'))
);
COMMENT ON TABLE "meta"."quantity_type" IS 'A dimensioned number type with a storage unit.';
COMMENT ON COLUMN "meta"."quantity_type"."id" IS 'Identifier of the row; what Meta<quantity_type> refers to.';
COMMENT ON COLUMN "meta"."quantity_type"."name" IS 'The type''s name.';
COMMENT ON COLUMN "meta"."quantity_type"."module" IS 'The declaring module.';
COMMENT ON COLUMN "meta"."quantity_type"."unit" IS 'The storage unit.';
COMMENT ON COLUMN "meta"."quantity_type"."scale" IS 'absolute, difference, ratio, dimensionless or count.';
COMMENT ON COLUMN "meta"."quantity_type"."production" IS 'The corresponding production quantity type, if any.';
COMMENT ON COLUMN "meta"."quantity_type"."pg_type" IS 'The domain that projects the type.';
COMMENT ON COLUMN "meta"."quantity_type"."doc" IS 'What the quantity means.';

CREATE TABLE "meta"."quantity_expression" (
    "expression" text NOT NULL,
    "unit" text NOT NULL,
    CONSTRAINT "quantity_expression__pk" PRIMARY KEY ("expression")
);
COMMENT ON TABLE "meta"."quantity_expression" IS 'A quantity expression used as a type, with the unit it resolves to.';
COMMENT ON COLUMN "meta"."quantity_expression"."expression" IS 'The normalised expression.';
COMMENT ON COLUMN "meta"."quantity_expression"."unit" IS 'The unit computed by unit algebra.';

CREATE TABLE "meta"."identifier_scheme" (
    "name" text NOT NULL,
    "module" text NOT NULL,
    "pg_type" text NOT NULL,
    "doc" text NOT NULL,
    CONSTRAINT "identifier_scheme__pk" PRIMARY KEY ("name")
);
COMMENT ON TABLE "meta"."identifier_scheme" IS 'A declared scheme of opaque identifiers.';
COMMENT ON COLUMN "meta"."identifier_scheme"."name" IS 'The scheme''s name.';
COMMENT ON COLUMN "meta"."identifier_scheme"."module" IS 'The declaring module.';
COMMENT ON COLUMN "meta"."identifier_scheme"."pg_type" IS 'The domain that projects the scheme.';
COMMENT ON COLUMN "meta"."identifier_scheme"."doc" IS 'What the identifiers identify.';

CREATE TABLE "meta"."enum" (
    "name" text NOT NULL,
    "module" text NOT NULL,
    "pg_type" text NOT NULL,
    "doc" text NOT NULL,
    CONSTRAINT "enum__pk" PRIMARY KEY ("name")
);
COMMENT ON TABLE "meta"."enum" IS 'A closed vocabulary pipeline code branches on.';
COMMENT ON COLUMN "meta"."enum"."name" IS 'The enum''s name.';
COMMENT ON COLUMN "meta"."enum"."module" IS 'The declaring module.';
COMMENT ON COLUMN "meta"."enum"."pg_type" IS 'The enum type that projects it.';
COMMENT ON COLUMN "meta"."enum"."doc" IS 'What the vocabulary distinguishes.';

CREATE TABLE "meta"."enum_member" (
    "enum" text NOT NULL,
    "name" text NOT NULL,
    "ordinal" integer NOT NULL,
    "doc" text NOT NULL,
    CONSTRAINT "enum_member__pk" PRIMARY KEY ("enum", "name"),
    CONSTRAINT "enum_member__uq__enum_ordinal" UNIQUE ("enum", "ordinal")
);
COMMENT ON TABLE "meta"."enum_member" IS 'A member of an enum.';
COMMENT ON COLUMN "meta"."enum_member"."enum" IS 'The enum.';
COMMENT ON COLUMN "meta"."enum_member"."name" IS 'The member''s name.';
COMMENT ON COLUMN "meta"."enum_member"."ordinal" IS 'Position in the enum, from 1.';
COMMENT ON COLUMN "meta"."enum_member"."doc" IS 'What the member means.';

CREATE TABLE "meta"."enum_facet" (
    "enum" text NOT NULL,
    "name" text NOT NULL,
    "ordinal" integer NOT NULL,
    "doc" text NOT NULL,
    CONSTRAINT "enum_facet__pk" PRIMARY KEY ("enum", "name"),
    CONSTRAINT "enum_facet__uq__enum_ordinal" UNIQUE ("enum", "ordinal")
);
COMMENT ON TABLE "meta"."enum_facet" IS 'A facet an enum declares: a property some of its members have.';
COMMENT ON COLUMN "meta"."enum_facet"."enum" IS 'The enum.';
COMMENT ON COLUMN "meta"."enum_facet"."name" IS 'The facet''s name.';
COMMENT ON COLUMN "meta"."enum_facet"."ordinal" IS 'Position among the enum''s facets, from 1.';
COMMENT ON COLUMN "meta"."enum_facet"."doc" IS 'What having the facet means.';

CREATE TABLE "meta"."enum_member_facet" (
    "enum" text NOT NULL,
    "member" text NOT NULL,
    "facet" text NOT NULL,
    CONSTRAINT "enum_member_facet__pk" PRIMARY KEY ("enum", "member", "facet")
);
COMMENT ON TABLE "meta"."enum_member_facet" IS 'A facet a member of an enum has.';
COMMENT ON COLUMN "meta"."enum_member_facet"."enum" IS 'The enum.';
COMMENT ON COLUMN "meta"."enum_member_facet"."member" IS 'The member.';
COMMENT ON COLUMN "meta"."enum_member_facet"."facet" IS 'A facet of the same enum the member has.';

CREATE TABLE "meta"."kind" (
    "id" uuid NOT NULL,
    "name" text NOT NULL,
    "module" text NOT NULL,
    "origin" text NOT NULL,
    "extends" text,
    "root" text NOT NULL,
    "abstract" boolean NOT NULL,
    "provenance" text NOT NULL,
    "provenance_attribute" text,
    "schema_name" text NOT NULL,
    "table_name" text NOT NULL,
    "doc" text NOT NULL,
    CONSTRAINT "kind__pk" PRIMARY KEY ("id"),
    CONSTRAINT "kind__uq__name" UNIQUE ("name"),
    CONSTRAINT "kind__ck__origin" CHECK ("origin" IN ('declared', 'slot_group')),
    CONSTRAINT "kind__ck__provenance" CHECK ("provenance" IN ('own', 'inherit', 'declaration', 'none')),
    CONSTRAINT "kind__ck__provenance_attribute" CHECK (("provenance" = 'inherit') = ("provenance_attribute" IS NOT NULL))
);
COMMENT ON TABLE "meta"."kind" IS 'A concept whose instances have identity; includes the kind each slot group expands to.';
COMMENT ON COLUMN "meta"."kind"."id" IS 'Identifier of the row; what Meta<kind> refers to.';
COMMENT ON COLUMN "meta"."kind"."name" IS 'The kind''s name.';
COMMENT ON COLUMN "meta"."kind"."module" IS 'The declaring module (a slot group''s form module).';
COMMENT ON COLUMN "meta"."kind"."origin" IS 'declared, or slot_group for the kind a slot group expands to.';
COMMENT ON COLUMN "meta"."kind"."extends" IS 'The kind this one refines.';
COMMENT ON COLUMN "meta"."kind"."root" IS 'The root of the refinement chain, which owns the identity.';
COMMENT ON COLUMN "meta"."kind"."abstract" IS 'Whether the kind has no direct instances.';
COMMENT ON COLUMN "meta"."kind"."provenance" IS 'own, inherit, declaration or none.';
COMMENT ON COLUMN "meta"."kind"."provenance_attribute" IS 'The reference whose record an inheriting instance shares.';
COMMENT ON COLUMN "meta"."kind"."schema_name" IS 'The schema of the kind''s table.';
COMMENT ON COLUMN "meta"."kind"."table_name" IS 'The kind''s table.';
COMMENT ON COLUMN "meta"."kind"."doc" IS 'What the kind is.';

CREATE TABLE "meta"."attribute" (
    "kind" text NOT NULL,
    "name" text NOT NULL,
    "position" integer NOT NULL,
    "container" text NOT NULL,
    "element_kind" text NOT NULL,
    "element" text NOT NULL,
    "optional" boolean NOT NULL,
    "is_unique" boolean NOT NULL,
    "default_value" text,
    "unit_from" text,
    "doc" text NOT NULL,
    CONSTRAINT "attribute__pk" PRIMARY KEY ("kind", "name"),
    CONSTRAINT "attribute__uq__kind_position" UNIQUE ("kind", "position"),
    CONSTRAINT "attribute__ck__container" CHECK ("container" IN ('scalar', 'range', 'array', 'set')),
    CONSTRAINT "attribute__ck__element_kind" CHECK ("element_kind" IN ('primitive', 'identifier', 'quantity', 'expression', 'enum', 'kind', 'record', 'meta', 'real', 'source_text'))
);
COMMENT ON TABLE "meta"."attribute" IS 'An attribute of a kind: a column of its table or a child table.';
COMMENT ON COLUMN "meta"."attribute"."kind" IS 'The kind.';
COMMENT ON COLUMN "meta"."attribute"."name" IS 'The attribute''s name.';
COMMENT ON COLUMN "meta"."attribute"."position" IS 'Declared position within the kind, from 1.';
COMMENT ON COLUMN "meta"."attribute"."container" IS 'How the type holds values: scalar, range, array or set.';
COMMENT ON COLUMN "meta"."attribute"."element_kind" IS 'What the element is: primitive, quantity, enum, kind and so on.';
COMMENT ON COLUMN "meta"."attribute"."element" IS 'The element: a type, scheme, enum or kind name, an expression or a Meta construct.';
COMMENT ON COLUMN "meta"."attribute"."optional" IS 'Whether an instance may have no such attribute.';
COMMENT ON COLUMN "meta"."attribute"."is_unique" IS 'Whether values are unique in addition to identity.';
COMMENT ON COLUMN "meta"."attribute"."default_value" IS 'The default, as canonical text.';
COMMENT ON COLUMN "meta"."attribute"."unit_from" IS 'For a Real: where its unit comes from (a path of references or `dimensionless`).';
COMMENT ON COLUMN "meta"."attribute"."doc" IS 'What the attribute means.';

CREATE TABLE "meta"."kind_identity" (
    "kind" text NOT NULL,
    "position" integer NOT NULL,
    "attribute" text NOT NULL,
    CONSTRAINT "kind_identity__pk" PRIMARY KEY ("kind", "position"),
    CONSTRAINT "kind_identity__uq__kind_attribute" UNIQUE ("kind", "attribute")
);
COMMENT ON TABLE "meta"."kind_identity" IS 'An attribute of a root kind''s identity, in encoding order.';
COMMENT ON COLUMN "meta"."kind_identity"."kind" IS 'The root kind.';
COMMENT ON COLUMN "meta"."kind_identity"."position" IS 'Position in the identity encoding, from 1.';
COMMENT ON COLUMN "meta"."kind_identity"."attribute" IS 'The identity attribute.';

CREATE TABLE "meta"."kind_unique" (
    "kind" text NOT NULL,
    "name" text NOT NULL,
    CONSTRAINT "kind_unique__pk" PRIMARY KEY ("kind", "name")
);
COMMENT ON TABLE "meta"."kind_unique" IS 'A composite uniqueness constraint of a kind.';
COMMENT ON COLUMN "meta"."kind_unique"."kind" IS 'The kind.';
COMMENT ON COLUMN "meta"."kind_unique"."name" IS 'The constraint''s name.';

CREATE TABLE "meta"."kind_unique_attribute" (
    "kind" text NOT NULL,
    "unique_name" text NOT NULL,
    "position" integer NOT NULL,
    "attribute" text NOT NULL,
    CONSTRAINT "kind_unique_attribute__pk" PRIMARY KEY ("kind", "unique_name", "position")
);
COMMENT ON TABLE "meta"."kind_unique_attribute" IS 'An attribute of a composite uniqueness constraint.';
COMMENT ON COLUMN "meta"."kind_unique_attribute"."kind" IS 'The kind.';
COMMENT ON COLUMN "meta"."kind_unique_attribute"."unique_name" IS 'The constraint.';
COMMENT ON COLUMN "meta"."kind_unique_attribute"."position" IS 'Position in the constraint, from 1.';
COMMENT ON COLUMN "meta"."kind_unique_attribute"."attribute" IS 'The attribute.';

CREATE TABLE "meta"."requirement" (
    "owner_type" text NOT NULL,
    "owner" text NOT NULL,
    "name" text NOT NULL,
    "enforced" text NOT NULL,
    "check_rule" text,
    "check_lower" double precision,
    "check_upper" double precision,
    "doc" text NOT NULL,
    CONSTRAINT "requirement__pk" PRIMARY KEY ("owner_type", "owner", "name"),
    CONSTRAINT "requirement__ck__owner_type" CHECK ("owner_type" IN ('kind', 'relation')),
    CONSTRAINT "requirement__ck__enforced" CHECK ("enforced" IN ('ddl', 'load', 'verify')),
    CONSTRAINT "requirement__ck__check_rule" CHECK ("check_rule" IN ('nonempty', 'positive', 'nonnegative', 'ordered', 'one_of_present', 'present_iff', 'within')),
    CONSTRAINT "requirement__ck__rule_for_ddl" CHECK (("enforced" = 'ddl') = ("check_rule" IS NOT NULL)),
    CONSTRAINT "requirement__ck__bounds_for_within" CHECK (("check_lower" IS NULL AND "check_upper" IS NULL) OR "check_rule" = 'within')
);
COMMENT ON TABLE "meta"."requirement" IS 'An invariant of a kind or a relation and where it is enforced.';
COMMENT ON COLUMN "meta"."requirement"."owner_type" IS 'kind or relation.';
COMMENT ON COLUMN "meta"."requirement"."owner" IS 'The name of the kind or of the relation.';
COMMENT ON COLUMN "meta"."requirement"."name" IS 'The invariant''s name.';
COMMENT ON COLUMN "meta"."requirement"."enforced" IS 'Where it is enforced: ddl, load or verify.';
COMMENT ON COLUMN "meta"."requirement"."check_rule" IS 'For ddl: nonempty, positive, nonnegative, ordered, one_of_present, present_iff or within.';
COMMENT ON COLUMN "meta"."requirement"."check_lower" IS 'For within: the lower bound, when stated.';
COMMENT ON COLUMN "meta"."requirement"."check_upper" IS 'For within: the upper bound, when stated.';
COMMENT ON COLUMN "meta"."requirement"."doc" IS 'The invariant.';

CREATE TABLE "meta"."requirement_attribute" (
    "owner_type" text NOT NULL,
    "owner" text NOT NULL,
    "requirement" text NOT NULL,
    "position" integer NOT NULL,
    "attribute" text NOT NULL,
    CONSTRAINT "requirement_attribute__pk" PRIMARY KEY ("owner_type", "owner", "requirement", "position")
);
COMMENT ON TABLE "meta"."requirement_attribute" IS 'A column a ddl invariant''s check is about: an attribute of a kind, a key or a value of a relation.';
COMMENT ON COLUMN "meta"."requirement_attribute"."owner_type" IS 'kind or relation.';
COMMENT ON COLUMN "meta"."requirement_attribute"."owner" IS 'The name of the kind or of the relation.';
COMMENT ON COLUMN "meta"."requirement_attribute"."requirement" IS 'The invariant.';
COMMENT ON COLUMN "meta"."requirement_attribute"."position" IS 'Position in the check, from 1.';
COMMENT ON COLUMN "meta"."requirement_attribute"."attribute" IS 'The column.';

CREATE TABLE "meta"."requirement_member" (
    "owner_type" text NOT NULL,
    "owner" text NOT NULL,
    "requirement" text NOT NULL,
    "position" integer NOT NULL,
    "member" text NOT NULL,
    CONSTRAINT "requirement_member__pk" PRIMARY KEY ("owner_type", "owner", "requirement", "position")
);
COMMENT ON TABLE "meta"."requirement_member" IS 'An enum member a present_iff invariant''s `in` list names.';
COMMENT ON COLUMN "meta"."requirement_member"."owner_type" IS 'kind or relation.';
COMMENT ON COLUMN "meta"."requirement_member"."owner" IS 'The name of the kind or of the relation.';
COMMENT ON COLUMN "meta"."requirement_member"."requirement" IS 'The invariant.';
COMMENT ON COLUMN "meta"."requirement_member"."position" IS 'Position in the list, from 1.';
COMMENT ON COLUMN "meta"."requirement_member"."member" IS 'The enum member.';

CREATE TABLE "meta"."relation" (
    "name" text NOT NULL,
    "module" text NOT NULL,
    "provenance" text NOT NULL,
    "provenance_key" text,
    "absence" text NOT NULL,
    "absence_default" text,
    "schema_name" text NOT NULL,
    "table_name" text NOT NULL,
    "doc" text NOT NULL,
    CONSTRAINT "relation__pk" PRIMARY KEY ("name"),
    CONSTRAINT "relation__ck__provenance" CHECK ("provenance" IN ('own', 'inherit', 'declaration', 'none')),
    CONSTRAINT "relation__ck__absence" CHECK ("absence" IN ('required', 'optional', 'default')),
    CONSTRAINT "relation__ck__provenance_key" CHECK (("provenance" = 'inherit') = ("provenance_key" IS NOT NULL)),
    CONSTRAINT "relation__ck__absence_default" CHECK (("absence" = 'default') = ("absence_default" IS NOT NULL))
);
COMMENT ON TABLE "meta"."relation" IS 'An n-ary fact keyed by typed roles.';
COMMENT ON COLUMN "meta"."relation"."name" IS 'The relation''s name.';
COMMENT ON COLUMN "meta"."relation"."module" IS 'The declaring module.';
COMMENT ON COLUMN "meta"."relation"."provenance" IS 'own, inherit, declaration or none.';
COMMENT ON COLUMN "meta"."relation"."provenance_key" IS 'The key whose record an inheriting row shares.';
COMMENT ON COLUMN "meta"."relation"."absence" IS 'What a missing row means: required, optional or default.';
COMMENT ON COLUMN "meta"."relation"."absence_default" IS 'The default, as canonical text.';
COMMENT ON COLUMN "meta"."relation"."schema_name" IS 'The schema of the relation''s table.';
COMMENT ON COLUMN "meta"."relation"."table_name" IS 'The relation''s table.';
COMMENT ON COLUMN "meta"."relation"."doc" IS 'What the relation asserts.';

CREATE TABLE "meta"."relation_key" (
    "relation" text NOT NULL,
    "name" text NOT NULL,
    "position" integer NOT NULL,
    "container" text NOT NULL,
    "element_kind" text NOT NULL,
    "element" text NOT NULL,
    "doc" text NOT NULL,
    CONSTRAINT "relation_key__pk" PRIMARY KEY ("relation", "name"),
    CONSTRAINT "relation_key__uq__relation_position" UNIQUE ("relation", "position"),
    CONSTRAINT "relation_key__ck__container" CHECK ("container" IN ('scalar', 'range', 'array', 'set')),
    CONSTRAINT "relation_key__ck__element_kind" CHECK ("element_kind" IN ('primitive', 'identifier', 'quantity', 'expression', 'enum', 'kind', 'record', 'meta', 'real', 'source_text'))
);
COMMENT ON TABLE "meta"."relation_key" IS 'A key role of a relation.';
COMMENT ON COLUMN "meta"."relation_key"."relation" IS 'The relation.';
COMMENT ON COLUMN "meta"."relation_key"."name" IS 'The role''s name.';
COMMENT ON COLUMN "meta"."relation_key"."position" IS 'Position in the key, from 1.';
COMMENT ON COLUMN "meta"."relation_key"."container" IS 'How the type holds values: scalar, range, array or set.';
COMMENT ON COLUMN "meta"."relation_key"."element_kind" IS 'What the element is: primitive, quantity, enum, kind and so on.';
COMMENT ON COLUMN "meta"."relation_key"."element" IS 'The element: a type, scheme, enum or kind name, an expression or a Meta construct.';
COMMENT ON COLUMN "meta"."relation_key"."doc" IS 'What the role is.';

CREATE TABLE "meta"."relation_value" (
    "relation" text NOT NULL,
    "name" text NOT NULL,
    "position" integer NOT NULL,
    "container" text NOT NULL,
    "element_kind" text NOT NULL,
    "element" text NOT NULL,
    "is_single" boolean NOT NULL,
    "optional" boolean NOT NULL,
    "default_value" text,
    "unit_from" text,
    "doc" text NOT NULL,
    CONSTRAINT "relation_value__pk" PRIMARY KEY ("relation", "name"),
    CONSTRAINT "relation_value__uq__relation_position" UNIQUE ("relation", "position"),
    CONSTRAINT "relation_value__ck__container" CHECK ("container" IN ('scalar', 'range', 'array', 'set')),
    CONSTRAINT "relation_value__ck__element_kind" CHECK ("element_kind" IN ('primitive', 'identifier', 'quantity', 'expression', 'enum', 'kind', 'record', 'meta', 'real', 'source_text'))
);
COMMENT ON TABLE "meta"."relation_value" IS 'A value column of a relation (a single value is named value).';
COMMENT ON COLUMN "meta"."relation_value"."relation" IS 'The relation.';
COMMENT ON COLUMN "meta"."relation_value"."name" IS 'The column''s name.';
COMMENT ON COLUMN "meta"."relation_value"."position" IS 'Position among the values, from 1.';
COMMENT ON COLUMN "meta"."relation_value"."container" IS 'How the type holds values: scalar, range, array or set.';
COMMENT ON COLUMN "meta"."relation_value"."element_kind" IS 'What the element is: primitive, quantity, enum, kind and so on.';
COMMENT ON COLUMN "meta"."relation_value"."element" IS 'The element: a type, scheme, enum or kind name, an expression or a Meta construct.';
COMMENT ON COLUMN "meta"."relation_value"."is_single" IS 'Whether this is the relation''s single value.';
COMMENT ON COLUMN "meta"."relation_value"."optional" IS 'Whether a row may have no such value.';
COMMENT ON COLUMN "meta"."relation_value"."default_value" IS 'The column default, as canonical text.';
COMMENT ON COLUMN "meta"."relation_value"."unit_from" IS 'For a Real: where its unit comes from (a path of references or `dimensionless`).';
COMMENT ON COLUMN "meta"."relation_value"."doc" IS 'What the value is.';

CREATE TABLE "meta"."transposition" (
    "owner_type" text NOT NULL,
    "owner" text NOT NULL,
    "rule" text NOT NULL,
    "diagonal" text NOT NULL,
    "by_index" text,
    CONSTRAINT "transposition__pk" PRIMARY KEY ("owner_type", "owner"),
    CONSTRAINT "transposition__ck__owner_type" CHECK ("owner_type" IN ('relation', 'slot_group')),
    CONSTRAINT "transposition__ck__rule" CHECK ("rule" IN ('ordered', 'symmetric', 'parity', 'reciprocal', 'linear', 'permutation_group')),
    CONSTRAINT "transposition__ck__diagonal" CHECK ("diagonal" IN ('forbidden', 'allowed')),
    CONSTRAINT "transposition__ck__by_for_parity" CHECK (("rule" = 'parity') = ("by_index" IS NOT NULL))
);
COMMENT ON TABLE "meta"."transposition" IS 'What happens to a fact when two of its roles are swapped.';
COMMENT ON COLUMN "meta"."transposition"."owner_type" IS 'relation or slot_group.';
COMMENT ON COLUMN "meta"."transposition"."owner" IS 'The relation''s name or the slot group''s qualified name.';
COMMENT ON COLUMN "meta"."transposition"."rule" IS 'ordered, symmetric, parity, reciprocal, linear or permutation_group.';
COMMENT ON COLUMN "meta"."transposition"."diagonal" IS 'forbidden or allowed: both roles may name one instance.';
COMMENT ON COLUMN "meta"."transposition"."by_index" IS 'For parity: the index whose parity sets the sign.';

CREATE TABLE "meta"."transposition_role" (
    "owner_type" text NOT NULL,
    "owner" text NOT NULL,
    "position" integer NOT NULL,
    "role" text NOT NULL,
    CONSTRAINT "transposition_role__pk" PRIMARY KEY ("owner_type", "owner", "position")
);
COMMENT ON TABLE "meta"."transposition_role" IS 'A role a transposition swaps, in order.';
COMMENT ON COLUMN "meta"."transposition_role"."owner_type" IS 'relation or slot_group.';
COMMENT ON COLUMN "meta"."transposition_role"."owner" IS 'The relation''s name or the slot group''s qualified name.';
COMMENT ON COLUMN "meta"."transposition_role"."position" IS 'Position among the roles, from 1.';
COMMENT ON COLUMN "meta"."transposition_role"."role" IS 'The key or subject role.';

CREATE TABLE "meta"."transposition_slot" (
    "owner_type" text NOT NULL,
    "owner" text NOT NULL,
    "position" integer NOT NULL,
    "slot" text NOT NULL,
    CONSTRAINT "transposition_slot__pk" PRIMARY KEY ("owner_type", "owner", "position"),
    CONSTRAINT "transposition_slot__uq__owner_type_owner_slot" UNIQUE ("owner_type", "owner", "slot")
);
COMMENT ON TABLE "meta"."transposition_slot" IS 'A slot or value that changes when roles are swapped (reciprocal, linear), in the order of the rule.';
COMMENT ON COLUMN "meta"."transposition_slot"."owner_type" IS 'relation or slot_group.';
COMMENT ON COLUMN "meta"."transposition_slot"."owner" IS 'The relation''s name or the slot group''s qualified name.';
COMMENT ON COLUMN "meta"."transposition_slot"."position" IS 'Position among the slots, from 1; the row and column of a linear matrix.';
COMMENT ON COLUMN "meta"."transposition_slot"."slot" IS 'The slot or value column.';

CREATE TABLE "meta"."transposition_matrix" (
    "owner_type" text NOT NULL,
    "owner" text NOT NULL,
    "row_position" integer NOT NULL,
    "column_position" integer NOT NULL,
    "coefficient" double precision NOT NULL,
    CONSTRAINT "transposition_matrix__pk" PRIMARY KEY ("owner_type", "owner", "row_position", "column_position")
);
COMMENT ON TABLE "meta"."transposition_matrix" IS 'An entry of the matrix a linear transposition multiplies the values of its slots by.';
COMMENT ON COLUMN "meta"."transposition_matrix"."owner_type" IS 'relation or slot_group.';
COMMENT ON COLUMN "meta"."transposition_matrix"."owner" IS 'The relation''s name or the slot group''s qualified name.';
COMMENT ON COLUMN "meta"."transposition_matrix"."row_position" IS 'Row, from 1: the slot whose swapped value it gives.';
COMMENT ON COLUMN "meta"."transposition_matrix"."column_position" IS 'Column, from 1: the slot whose value it multiplies.';
COMMENT ON COLUMN "meta"."transposition_matrix"."coefficient" IS 'The entry.';

CREATE TABLE "meta"."transposition_permutation" (
    "owner_type" text NOT NULL,
    "owner" text NOT NULL,
    "permutation" integer NOT NULL,
    "position" integer NOT NULL,
    "role" text NOT NULL,
    CONSTRAINT "transposition_permutation__pk" PRIMARY KEY ("owner_type", "owner", "permutation", "position")
);
COMMENT ON TABLE "meta"."transposition_permutation" IS 'A role permutation that leaves a fact unchanged (permutation_group).';
COMMENT ON COLUMN "meta"."transposition_permutation"."owner_type" IS 'relation or slot_group.';
COMMENT ON COLUMN "meta"."transposition_permutation"."owner" IS 'The relation''s name or the slot group''s qualified name.';
COMMENT ON COLUMN "meta"."transposition_permutation"."permutation" IS 'Which permutation, from 1.';
COMMENT ON COLUMN "meta"."transposition_permutation"."position" IS 'Position in the arrangement, from 1.';
COMMENT ON COLUMN "meta"."transposition_permutation"."role" IS 'The role placed there.';

CREATE TABLE "meta"."contract" (
    "id" uuid NOT NULL,
    "name" text NOT NULL,
    "module" text NOT NULL,
    "doc" text NOT NULL,
    CONSTRAINT "contract__pk" PRIMARY KEY ("id"),
    CONSTRAINT "contract__uq__name" UNIQUE ("name")
);
COMMENT ON TABLE "meta"."contract" IS 'What a form consumes and produces.';
COMMENT ON COLUMN "meta"."contract"."id" IS 'Identifier of the row; what Meta<contract> refers to.';
COMMENT ON COLUMN "meta"."contract"."name" IS 'The contract''s name.';
COMMENT ON COLUMN "meta"."contract"."module" IS 'The declaring module.';
COMMENT ON COLUMN "meta"."contract"."doc" IS 'The function the contract describes.';

CREATE TABLE "meta"."contract_role" (
    "contract" text NOT NULL,
    "name" text NOT NULL,
    "position" integer NOT NULL,
    "kind" text NOT NULL,
    "doc" text NOT NULL,
    CONSTRAINT "contract_role__pk" PRIMARY KEY ("contract", "name"),
    CONSTRAINT "contract_role__uq__contract_position" UNIQUE ("contract", "position")
);
COMMENT ON TABLE "meta"."contract_role" IS 'A role of a contract: a single subject an evaluation is about.';
COMMENT ON COLUMN "meta"."contract_role"."contract" IS 'The contract.';
COMMENT ON COLUMN "meta"."contract_role"."name" IS 'The role''s name.';
COMMENT ON COLUMN "meta"."contract_role"."position" IS 'Position, from 1.';
COMMENT ON COLUMN "meta"."contract_role"."kind" IS 'The kind of the subject or of the set''s elements.';
COMMENT ON COLUMN "meta"."contract_role"."doc" IS 'What the role is.';

CREATE TABLE "meta"."contract_set" (
    "contract" text NOT NULL,
    "name" text NOT NULL,
    "position" integer NOT NULL,
    "kind" text NOT NULL,
    "doc" text NOT NULL,
    CONSTRAINT "contract_set__pk" PRIMARY KEY ("contract", "name"),
    CONSTRAINT "contract_set__uq__contract_position" UNIQUE ("contract", "position")
);
COMMENT ON TABLE "meta"."contract_set" IS 'A set of a contract: an index set of entities an evaluation is about.';
COMMENT ON COLUMN "meta"."contract_set"."contract" IS 'The contract.';
COMMENT ON COLUMN "meta"."contract_set"."name" IS 'The set''s name.';
COMMENT ON COLUMN "meta"."contract_set"."position" IS 'Position, from 1.';
COMMENT ON COLUMN "meta"."contract_set"."kind" IS 'The kind of the subject or of the set''s elements.';
COMMENT ON COLUMN "meta"."contract_set"."doc" IS 'What the set is.';

CREATE TABLE "meta"."contract_argument" (
    "contract" text NOT NULL,
    "name" text NOT NULL,
    "position" integer NOT NULL,
    "container" text NOT NULL,
    "element_kind" text NOT NULL,
    "element" text NOT NULL,
    "basis" uuid,
    "doc" text NOT NULL,
    CONSTRAINT "contract_argument__pk" PRIMARY KEY ("contract", "name"),
    CONSTRAINT "contract_argument__uq__contract_position" UNIQUE ("contract", "position"),
    CONSTRAINT "contract_argument__ck__container" CHECK ("container" IN ('scalar', 'range', 'array', 'set')),
    CONSTRAINT "contract_argument__ck__element_kind" CHECK ("element_kind" IN ('primitive', 'identifier', 'quantity', 'expression', 'enum', 'kind', 'record', 'meta', 'real', 'source_text'))
);
COMMENT ON TABLE "meta"."contract_argument" IS 'An argument of a contract.';
COMMENT ON COLUMN "meta"."contract_argument"."contract" IS 'The contract.';
COMMENT ON COLUMN "meta"."contract_argument"."name" IS 'The argument''s name.';
COMMENT ON COLUMN "meta"."contract_argument"."position" IS 'Position, from 1.';
COMMENT ON COLUMN "meta"."contract_argument"."container" IS 'How the type holds values: scalar, range, array or set.';
COMMENT ON COLUMN "meta"."contract_argument"."element_kind" IS 'What the element is: primitive, quantity, enum, kind and so on.';
COMMENT ON COLUMN "meta"."contract_argument"."element" IS 'The element: a type, scheme, enum or kind name, an expression or a Meta construct.';
COMMENT ON COLUMN "meta"."contract_argument"."basis" IS 'For a composition: the declared composition basis entity its values are on (its identifier).';
COMMENT ON COLUMN "meta"."contract_argument"."doc" IS 'What the argument is.';

CREATE TABLE "meta"."contract_argument_set" (
    "contract" text NOT NULL,
    "argument" text NOT NULL,
    "position" integer NOT NULL,
    "set_name" text NOT NULL,
    CONSTRAINT "contract_argument_set__pk" PRIMARY KEY ("contract", "argument", "position")
);
COMMENT ON TABLE "meta"."contract_argument_set" IS 'A set an indexed argument of a contract ranges over, in index order.';
COMMENT ON COLUMN "meta"."contract_argument_set"."contract" IS 'The contract.';
COMMENT ON COLUMN "meta"."contract_argument_set"."argument" IS 'The argument.';
COMMENT ON COLUMN "meta"."contract_argument_set"."position" IS 'Position among the argument''s indices, from 1.';
COMMENT ON COLUMN "meta"."contract_argument_set"."set_name" IS 'The contract set the index ranges over.';

CREATE TABLE "meta"."contract_output" (
    "contract" text NOT NULL,
    "name" text NOT NULL,
    "position" integer NOT NULL,
    "container" text NOT NULL,
    "element_kind" text NOT NULL,
    "element" text NOT NULL,
    "observable" uuid,
    "observable_from_set" boolean NOT NULL,
    "doc" text NOT NULL,
    CONSTRAINT "contract_output__pk" PRIMARY KEY ("contract", "name"),
    CONSTRAINT "contract_output__uq__contract_position" UNIQUE ("contract", "position"),
    CONSTRAINT "contract_output__ck__container" CHECK ("container" IN ('scalar', 'range', 'array', 'set')),
    CONSTRAINT "contract_output__ck__element_kind" CHECK ("element_kind" IN ('primitive', 'identifier', 'quantity', 'expression', 'enum', 'kind', 'record', 'meta', 'real', 'source_text')),
    CONSTRAINT "contract_output__ck__observable_or_from_set" CHECK (NOT ("observable_from_set" AND "observable" IS NOT NULL))
);
COMMENT ON TABLE "meta"."contract_output" IS 'An output of a contract.';
COMMENT ON COLUMN "meta"."contract_output"."contract" IS 'The contract.';
COMMENT ON COLUMN "meta"."contract_output"."name" IS 'The output''s name.';
COMMENT ON COLUMN "meta"."contract_output"."position" IS 'Position, from 1.';
COMMENT ON COLUMN "meta"."contract_output"."container" IS 'How the type holds values: scalar, range, array or set.';
COMMENT ON COLUMN "meta"."contract_output"."element_kind" IS 'What the element is: primitive, quantity, enum, kind and so on.';
COMMENT ON COLUMN "meta"."contract_output"."element" IS 'The element: a type, scheme, enum or kind name, an expression or a Meta construct.';
COMMENT ON COLUMN "meta"."contract_output"."observable" IS 'The declared observable entity the output denotes (its identifier).';
COMMENT ON COLUMN "meta"."contract_output"."observable_from_set" IS 'Whether the observable is given by a slot of the implementing form (form_output_observable).';
COMMENT ON COLUMN "meta"."contract_output"."doc" IS 'What the output is.';

CREATE TABLE "meta"."form" (
    "id" uuid NOT NULL,
    "name" text NOT NULL,
    "module" text NOT NULL,
    "implements" text NOT NULL,
    "completeness" text NOT NULL,
    "status" text NOT NULL,
    "doc" text NOT NULL,
    CONSTRAINT "form__pk" PRIMARY KEY ("id"),
    CONSTRAINT "form__uq__name" UNIQUE ("name"),
    CONSTRAINT "form__uq__name_implements" UNIQUE ("name", "implements"),
    CONSTRAINT "form__ck__completeness" CHECK ("completeness" IN ('fully_declared', 'structure_declared_equation_external', 'opaque_bundle')),
    CONSTRAINT "form__ck__status" CHECK ("status" IN ('catalogued', 'expressed'))
);
COMMENT ON TABLE "meta"."form" IS 'A model form: a catalogued family of equations.';
COMMENT ON COLUMN "meta"."form"."id" IS 'Identifier of the row; what Meta<form> refers to.';
COMMENT ON COLUMN "meta"."form"."name" IS 'The form''s name.';
COMMENT ON COLUMN "meta"."form"."module" IS 'The declaring module.';
COMMENT ON COLUMN "meta"."form"."implements" IS 'The contract it implements.';
COMMENT ON COLUMN "meta"."form"."completeness" IS 'How much of the form is declared.';
COMMENT ON COLUMN "meta"."form"."status" IS 'catalogued or expressed; whether a form is qualified is derived from recorded runs (qual.form_qualification).';
COMMENT ON COLUMN "meta"."form"."doc" IS 'What the form is.';

CREATE TABLE "meta"."form_citation" (
    "form" text NOT NULL,
    "position" integer NOT NULL,
    "citation" text NOT NULL,
    CONSTRAINT "form_citation__pk" PRIMARY KEY ("form", "position")
);
COMMENT ON TABLE "meta"."form_citation" IS 'A citation of a form, in declared order.';
COMMENT ON COLUMN "meta"."form_citation"."form" IS 'The form.';
COMMENT ON COLUMN "meta"."form_citation"."position" IS 'Position, from 1.';
COMMENT ON COLUMN "meta"."form_citation"."citation" IS 'The cited source key.';

CREATE TABLE "meta"."form_local" (
    "form" text NOT NULL,
    "name" text NOT NULL,
    "position" integer NOT NULL,
    "expression" text NOT NULL,
    "content_hash" text NOT NULL,
    CONSTRAINT "form_local__pk" PRIMARY KEY ("form", "name"),
    CONSTRAINT "form_local__uq__form_position" UNIQUE ("form", "position"),
    CONSTRAINT "form_local__ck__content_hash" CHECK (length("content_hash") = 64)
);
COMMENT ON TABLE "meta"."form_local" IS 'A form''s local: a local binding, evaluated in declared order.';
COMMENT ON COLUMN "meta"."form_local"."form" IS 'The form.';
COMMENT ON COLUMN "meta"."form_local"."name" IS 'The local''s name.';
COMMENT ON COLUMN "meta"."form_local"."position" IS 'Position in declared order, from 1.';
COMMENT ON COLUMN "meta"."form_local"."expression" IS 'The expression text as declared.';
COMMENT ON COLUMN "meta"."form_local"."content_hash" IS 'SHA-256 (hex) of the canonical serialisation of the expression''s typed tree.';

CREATE TABLE "meta"."form_output" (
    "form" text NOT NULL,
    "contract" text NOT NULL,
    "name" text NOT NULL,
    "position" integer NOT NULL,
    "expression" text NOT NULL,
    "content_hash" text NOT NULL,
    "evaluation_hash" text NOT NULL,
    CONSTRAINT "form_output__pk" PRIMARY KEY ("form", "name"),
    CONSTRAINT "form_output__uq__form_position" UNIQUE ("form", "position"),
    CONSTRAINT "form_output__ck__content_hash" CHECK (length("content_hash") = 64),
    CONSTRAINT "form_output__ck__evaluation_hash" CHECK (length("evaluation_hash") = 64)
);
COMMENT ON TABLE "meta"."form_output" IS 'A form''s output: the expression of one contract output.';
COMMENT ON COLUMN "meta"."form_output"."form" IS 'The form.';
COMMENT ON COLUMN "meta"."form_output"."contract" IS 'The contract the form implements.';
COMMENT ON COLUMN "meta"."form_output"."name" IS 'The output''s name.';
COMMENT ON COLUMN "meta"."form_output"."position" IS 'Position in declared order, from 1.';
COMMENT ON COLUMN "meta"."form_output"."expression" IS 'The expression text as declared.';
COMMENT ON COLUMN "meta"."form_output"."content_hash" IS 'SHA-256 (hex) of the canonical serialisation of the expression''s typed tree.';
COMMENT ON COLUMN "meta"."form_output"."evaluation_hash" IS 'SHA-256 (hex) of what evaluating this output reads from the form''s text: its locals, this output''s expression and its implicit blocks, each in canonical serialisation; what a qualification run records.';

CREATE TABLE "meta"."form_output_observable" (
    "form" text NOT NULL,
    "contract" text NOT NULL,
    "output" text NOT NULL,
    "slot" text NOT NULL,
    CONSTRAINT "form_output_observable__pk" PRIMARY KEY ("form", "output")
);
COMMENT ON TABLE "meta"."form_output_observable" IS 'The slot that supplies the observable of an output a contract declares observable_from_set.';
COMMENT ON COLUMN "meta"."form_output_observable"."form" IS 'The form.';
COMMENT ON COLUMN "meta"."form_output_observable"."contract" IS 'The contract the form implements.';
COMMENT ON COLUMN "meta"."form_output_observable"."output" IS 'The output.';
COMMENT ON COLUMN "meta"."form_output_observable"."slot" IS 'The slot''s qualified name (form.group.slot): a required observable reference.';

CREATE TABLE "meta"."form_convention" (
    "form" text NOT NULL,
    "name" text NOT NULL,
    "position" integer NOT NULL,
    "kind" text NOT NULL,
    CONSTRAINT "form_convention__pk" PRIMARY KEY ("form", "name"),
    CONSTRAINT "form_convention__uq__form_position" UNIQUE ("form", "position")
);
COMMENT ON TABLE "meta"."form_convention" IS 'A convention fact a form reads (`convention.<name>` in its expressions): a quantity-typed attribute of the convention-set kind.';
COMMENT ON COLUMN "meta"."form_convention"."form" IS 'The form.';
COMMENT ON COLUMN "meta"."form_convention"."name" IS 'The convention-set attribute the form reads.';
COMMENT ON COLUMN "meta"."form_convention"."position" IS 'Position among the form''s convention facts, from 1.';
COMMENT ON COLUMN "meta"."form_convention"."kind" IS 'The kind that declares the attribute (the kind bound to convention_set or one it extends).';

CREATE TABLE "meta"."form_implicit" (
    "form" text NOT NULL,
    "name" text NOT NULL,
    "position" integer NOT NULL,
    "select_rule" text NOT NULL,
    "select_expression" text,
    "select_hash" text,
    "doc" text NOT NULL,
    CONSTRAINT "form_implicit__pk" PRIMARY KEY ("form", "name"),
    CONSTRAINT "form_implicit__uq__form_position" UNIQUE ("form", "position"),
    CONSTRAINT "form_implicit__ck__select_rule" CHECK ("select_rule" IN ('unique', 'smallest', 'largest', 'by')),
    CONSTRAINT "form_implicit__ck__select" CHECK (("select_rule" = 'by') = ("select_expression" IS NOT NULL) AND ("select_expression" IS NULL) = ("select_hash" IS NULL) AND ("select_hash" IS NULL OR length("select_hash") = 64))
);
COMMENT ON TABLE "meta"."form_implicit" IS 'An implicit block of a form: unknowns defined by residuals that vanish.';
COMMENT ON COLUMN "meta"."form_implicit"."form" IS 'The form.';
COMMENT ON COLUMN "meta"."form_implicit"."name" IS 'The block''s name within the form.';
COMMENT ON COLUMN "meta"."form_implicit"."position" IS 'Position among the form''s blocks, from 1.';
COMMENT ON COLUMN "meta"."form_implicit"."select_rule" IS 'How one root is chosen: unique, smallest, largest or by.';
COMMENT ON COLUMN "meta"."form_implicit"."select_expression" IS 'For `by`: the expression minimised over the roots, as declared.';
COMMENT ON COLUMN "meta"."form_implicit"."select_hash" IS 'For `by`: SHA-256 (hex) of the canonical serialisation of its typed tree.';
COMMENT ON COLUMN "meta"."form_implicit"."doc" IS 'What the block determines.';

CREATE TABLE "meta"."form_unknown" (
    "form" text NOT NULL,
    "block" text NOT NULL,
    "name" text NOT NULL,
    "position" integer NOT NULL,
    "container" text NOT NULL,
    "element_kind" text NOT NULL,
    "element" text NOT NULL,
    CONSTRAINT "form_unknown__pk" PRIMARY KEY ("form", "block", "name"),
    CONSTRAINT "form_unknown__uq__form_block_position" UNIQUE ("form", "block", "position"),
    CONSTRAINT "form_unknown__ck__container" CHECK ("container" IN ('scalar', 'range', 'array', 'set')),
    CONSTRAINT "form_unknown__ck__element_kind" CHECK ("element_kind" IN ('primitive', 'identifier', 'quantity', 'expression', 'enum', 'kind', 'record', 'meta', 'real', 'source_text'))
);
COMMENT ON TABLE "meta"."form_unknown" IS 'An unknown of an implicit block: a quantity, optionally over sets of the contract.';
COMMENT ON COLUMN "meta"."form_unknown"."form" IS 'The form.';
COMMENT ON COLUMN "meta"."form_unknown"."block" IS 'The implicit block.';
COMMENT ON COLUMN "meta"."form_unknown"."name" IS 'The unknown''s name.';
COMMENT ON COLUMN "meta"."form_unknown"."position" IS 'Position among the block''s unknowns, from 1.';
COMMENT ON COLUMN "meta"."form_unknown"."container" IS 'How the type holds values: scalar, range, array or set.';
COMMENT ON COLUMN "meta"."form_unknown"."element_kind" IS 'What the element is: primitive, quantity, enum, kind and so on.';
COMMENT ON COLUMN "meta"."form_unknown"."element" IS 'The element: a type, scheme, enum or kind name, an expression or a Meta construct.';

CREATE TABLE "meta"."form_unknown_set" (
    "form" text NOT NULL,
    "contract" text NOT NULL,
    "block" text NOT NULL,
    "unknown" text NOT NULL,
    "position" integer NOT NULL,
    "set_name" text NOT NULL,
    CONSTRAINT "form_unknown_set__pk" PRIMARY KEY ("form", "block", "unknown", "position")
);
COMMENT ON TABLE "meta"."form_unknown_set" IS 'A set an unknown of an implicit block ranges over, in index order.';
COMMENT ON COLUMN "meta"."form_unknown_set"."form" IS 'The form.';
COMMENT ON COLUMN "meta"."form_unknown_set"."contract" IS 'The contract the form implements.';
COMMENT ON COLUMN "meta"."form_unknown_set"."block" IS 'The implicit block.';
COMMENT ON COLUMN "meta"."form_unknown_set"."unknown" IS 'The unknown.';
COMMENT ON COLUMN "meta"."form_unknown_set"."position" IS 'Position among the unknown''s indices, from 1.';
COMMENT ON COLUMN "meta"."form_unknown_set"."set_name" IS 'The contract set the index ranges over.';

CREATE TABLE "meta"."form_unknown_bound" (
    "form" text NOT NULL,
    "block" text NOT NULL,
    "unknown" text NOT NULL,
    "bound" text NOT NULL,
    "number" double precision,
    "expression" text,
    "content_hash" text,
    CONSTRAINT "form_unknown_bound__pk" PRIMARY KEY ("form", "block", "unknown", "bound"),
    CONSTRAINT "form_unknown_bound__ck__bound" CHECK ("bound" IN ('lower', 'upper', 'start')),
    CONSTRAINT "form_unknown_bound__ck__value" CHECK (("number" IS NULL) <> ("expression" IS NULL)),
    CONSTRAINT "form_unknown_bound__ck__content_hash" CHECK (("expression" IS NULL) = ("content_hash" IS NULL) AND ("content_hash" IS NULL OR length("content_hash") = 64))
);
COMMENT ON TABLE "meta"."form_unknown_bound" IS 'A bound or the start of an unknown: a number in storage units, or an expression.';
COMMENT ON COLUMN "meta"."form_unknown_bound"."form" IS 'The form.';
COMMENT ON COLUMN "meta"."form_unknown_bound"."block" IS 'The implicit block.';
COMMENT ON COLUMN "meta"."form_unknown_bound"."unknown" IS 'The unknown.';
COMMENT ON COLUMN "meta"."form_unknown_bound"."bound" IS 'lower, upper or start.';
COMMENT ON COLUMN "meta"."form_unknown_bound"."number" IS 'The value, in storage units, when a number was declared.';
COMMENT ON COLUMN "meta"."form_unknown_bound"."expression" IS 'The expression text as declared, when one was.';
COMMENT ON COLUMN "meta"."form_unknown_bound"."content_hash" IS 'SHA-256 (hex) of the canonical serialisation of the expression''s typed tree.';

CREATE TABLE "meta"."form_residual" (
    "form" text NOT NULL,
    "block" text NOT NULL,
    "position" integer NOT NULL,
    "expression" text NOT NULL,
    "content_hash" text NOT NULL,
    CONSTRAINT "form_residual__pk" PRIMARY KEY ("form", "block", "position"),
    CONSTRAINT "form_residual__ck__content_hash" CHECK (length("content_hash") = 64)
);
COMMENT ON TABLE "meta"."form_residual" IS 'A residual of an implicit block: an expression that vanishes at the solution, or one with `for` clauses that states a residual for each element.';
COMMENT ON COLUMN "meta"."form_residual"."form" IS 'The form.';
COMMENT ON COLUMN "meta"."form_residual"."block" IS 'The implicit block.';
COMMENT ON COLUMN "meta"."form_residual"."position" IS 'Position among the block''s residuals, from 1.';
COMMENT ON COLUMN "meta"."form_residual"."expression" IS 'The residual text as declared.';
COMMENT ON COLUMN "meta"."form_residual"."content_hash" IS 'SHA-256 (hex) of the canonical serialisation of the residual''s typed tree.';

CREATE TABLE "meta"."slot_group" (
    "id" uuid NOT NULL,
    "qualified_name" text NOT NULL,
    "form" text NOT NULL,
    "name" text NOT NULL,
    "kind" text NOT NULL,
    "table_name" text NOT NULL,
    "doc" text NOT NULL,
    CONSTRAINT "slot_group__pk" PRIMARY KEY ("id"),
    CONSTRAINT "slot_group__uq__qualified_name" UNIQUE ("qualified_name")
);
COMMENT ON TABLE "meta"."slot_group" IS 'The parameters one source fits together for one subject tuple.';
COMMENT ON COLUMN "meta"."slot_group"."id" IS 'Identifier of the row; what Meta<slot_group> refers to.';
COMMENT ON COLUMN "meta"."slot_group"."qualified_name" IS 'form.group.';
COMMENT ON COLUMN "meta"."slot_group"."form" IS 'The form.';
COMMENT ON COLUMN "meta"."slot_group"."name" IS 'The group''s name within the form.';
COMMENT ON COLUMN "meta"."slot_group"."kind" IS 'The kind the group expands to.';
COMMENT ON COLUMN "meta"."slot_group"."table_name" IS 'The group''s table in schema param.';
COMMENT ON COLUMN "meta"."slot_group"."doc" IS 'What the group fits.';

CREATE TABLE "meta"."slot_group_subject" (
    "slot_group" text NOT NULL,
    "name" text NOT NULL,
    "position" integer NOT NULL,
    "kind" text NOT NULL,
    "binds_to_type" text,
    "binds_to" text,
    "doc" text NOT NULL,
    CONSTRAINT "slot_group_subject__pk" PRIMARY KEY ("slot_group", "name"),
    CONSTRAINT "slot_group_subject__uq__slot_group_position" UNIQUE ("slot_group", "position"),
    CONSTRAINT "slot_group_subject__ck__binds_to_type" CHECK ("binds_to_type" IN ('role', 'set')),
    CONSTRAINT "slot_group_subject__ck__binding" CHECK (("binds_to_type" IS NULL) = ("binds_to" IS NULL))
);
COMMENT ON TABLE "meta"."slot_group_subject" IS 'A subject role of a slot group.';
COMMENT ON COLUMN "meta"."slot_group_subject"."slot_group" IS 'The group''s qualified name.';
COMMENT ON COLUMN "meta"."slot_group_subject"."name" IS 'The role''s name.';
COMMENT ON COLUMN "meta"."slot_group_subject"."position" IS 'Position in the subject tuple, from 1.';
COMMENT ON COLUMN "meta"."slot_group_subject"."kind" IS 'The kind the role refers to.';
COMMENT ON COLUMN "meta"."slot_group_subject"."binds_to_type" IS 'What the role is bound to in the form''s contract: role or set.';
COMMENT ON COLUMN "meta"."slot_group_subject"."binds_to" IS 'The contract role or set the role is bound to.';
COMMENT ON COLUMN "meta"."slot_group_subject"."doc" IS 'What the role is.';

CREATE TABLE "meta"."family" (
    "id" uuid NOT NULL,
    "qualified_name" text NOT NULL,
    "slot_group" text NOT NULL,
    "name" text NOT NULL,
    "table_name" text NOT NULL,
    "interval_lower" text,
    "interval_upper" text,
    "doc" text NOT NULL,
    CONSTRAINT "family__pk" PRIMARY KEY ("id"),
    CONSTRAINT "family__uq__qualified_name" UNIQUE ("qualified_name"),
    CONSTRAINT "family__ck__interval" CHECK (("interval_lower" IS NULL) = ("interval_upper" IS NULL))
);
COMMENT ON TABLE "meta"."family" IS 'Slots that repeat over an index, projected to a child table of a slot group.';
COMMENT ON COLUMN "meta"."family"."id" IS 'Identifier of the row; what Meta<family> refers to.';
COMMENT ON COLUMN "meta"."family"."qualified_name" IS 'form.group.family.';
COMMENT ON COLUMN "meta"."family"."slot_group" IS 'The group''s qualified name.';
COMMENT ON COLUMN "meta"."family"."name" IS 'The family''s name within the group.';
COMMENT ON COLUMN "meta"."family"."table_name" IS 'The family''s table in schema param.';
COMMENT ON COLUMN "meta"."family"."interval_lower" IS 'The slot bounding each piece below, if the family has an interval.';
COMMENT ON COLUMN "meta"."family"."interval_upper" IS 'The slot bounding each piece above.';
COMMENT ON COLUMN "meta"."family"."doc" IS 'What the family holds.';

CREATE TABLE "meta"."family_index" (
    "family" text NOT NULL,
    "name" text NOT NULL,
    "position" integer NOT NULL,
    "element_kind" text NOT NULL,
    "element" text NOT NULL,
    "minimum" bigint,
    "doc" text NOT NULL,
    CONSTRAINT "family_index__pk" PRIMARY KEY ("family", "name"),
    CONSTRAINT "family_index__uq__family_position" UNIQUE ("family", "position"),
    CONSTRAINT "family_index__ck__element_kind" CHECK ("element_kind" IN ('primitive', 'identifier', 'quantity', 'expression', 'enum', 'kind', 'record', 'meta', 'real', 'source_text'))
);
COMMENT ON TABLE "meta"."family_index" IS 'An index of a family.';
COMMENT ON COLUMN "meta"."family_index"."family" IS 'The family''s qualified name.';
COMMENT ON COLUMN "meta"."family_index"."name" IS 'The index''s name.';
COMMENT ON COLUMN "meta"."family_index"."position" IS 'Position in the key, from 1.';
COMMENT ON COLUMN "meta"."family_index"."element_kind" IS 'primitive, enum and so on.';
COMMENT ON COLUMN "meta"."family_index"."element" IS 'The index type.';
COMMENT ON COLUMN "meta"."family_index"."minimum" IS 'The smallest index value, for an Integer index.';
COMMENT ON COLUMN "meta"."family_index"."doc" IS 'What the index counts.';

CREATE TABLE "meta"."slot" (
    "id" uuid NOT NULL,
    "qualified_name" text NOT NULL,
    "slot_group" text NOT NULL,
    "family" text,
    "name" text NOT NULL,
    "position" integer NOT NULL,
    "shape" text NOT NULL,
    "element_kind" text,
    "element" text,
    "accepts" text,
    "references_contract" text,
    "presence" text NOT NULL,
    "observable" uuid,
    "doc" text NOT NULL,
    CONSTRAINT "slot__pk" PRIMARY KEY ("id"),
    CONSTRAINT "slot__uq__qualified_name" UNIQUE ("qualified_name"),
    CONSTRAINT "slot__uq__slot_group_family_name" UNIQUE NULLS NOT DISTINCT ("slot_group", "family", "name"),
    CONSTRAINT "slot__ck__shape" CHECK ("shape" IN ('quantity', 'enum', 'reference', 'tabulated_function', 'nested_set', 'set_reference')),
    CONSTRAINT "slot__ck__presence" CHECK ("presence" IN ('required', 'stateful')),
    CONSTRAINT "slot__ck__element_kind" CHECK ("element_kind" IN ('primitive', 'identifier', 'quantity', 'expression', 'enum', 'kind', 'record', 'meta', 'real', 'source_text')),
    CONSTRAINT "slot__ck__nested_set" CHECK (("shape" = 'nested_set') = ("accepts" IS NOT NULL)),
    CONSTRAINT "slot__ck__set_reference" CHECK (("shape" = 'set_reference') = ("references_contract" IS NOT NULL))
);
COMMENT ON TABLE "meta"."slot" IS 'A slot of a slot group or of one of its families.';
COMMENT ON COLUMN "meta"."slot"."id" IS 'Identifier of the row; what Meta<slot> refers to.';
COMMENT ON COLUMN "meta"."slot"."qualified_name" IS 'form.group.slot, or form.group.family.slot.';
COMMENT ON COLUMN "meta"."slot"."slot_group" IS 'The group''s qualified name.';
COMMENT ON COLUMN "meta"."slot"."family" IS 'The family''s qualified name, for a family slot.';
COMMENT ON COLUMN "meta"."slot"."name" IS 'The slot''s name.';
COMMENT ON COLUMN "meta"."slot"."position" IS 'Position among the owner''s slots, from 1.';
COMMENT ON COLUMN "meta"."slot"."shape" IS 'quantity, enum, reference, tabulated_function, nested_set or set_reference.';
COMMENT ON COLUMN "meta"."slot"."element_kind" IS 'The value''s element kind; null for a nested set or a set reference.';
COMMENT ON COLUMN "meta"."slot"."element" IS 'The value''s type; null for a nested set or a set reference.';
COMMENT ON COLUMN "meta"."slot"."accepts" IS 'For a nested set: the contract its form implements.';
COMMENT ON COLUMN "meta"."slot"."references_contract" IS 'For a set reference: the contract the form of the referenced set implements.';
COMMENT ON COLUMN "meta"."slot"."presence" IS 'required or stateful.';
COMMENT ON COLUMN "meta"."slot"."observable" IS 'The declared observable entity the slot denotes (its identifier).';
COMMENT ON COLUMN "meta"."slot"."doc" IS 'What the slot is.';

CREATE TABLE "meta"."subform_slot" (
    "id" uuid NOT NULL,
    "qualified_name" text NOT NULL,
    "form" text NOT NULL,
    "name" text NOT NULL,
    "position" integer NOT NULL,
    "accepts" text NOT NULL,
    "multiplicity" text NOT NULL,
    "per" text NOT NULL,
    "doc" text NOT NULL,
    CONSTRAINT "subform_slot__pk" PRIMARY KEY ("id"),
    CONSTRAINT "subform_slot__uq__qualified_name" UNIQUE ("qualified_name"),
    CONSTRAINT "subform_slot__ck__multiplicity" CHECK ("multiplicity" IN ('one', 'optional', 'many')),
    CONSTRAINT "subform_slot__ck__per" CHECK ("per" IN ('model', 'subject'))
);
COMMENT ON TABLE "meta"."subform_slot" IS 'A slot for a sub-form: a choice of form implementing a contract.';
COMMENT ON COLUMN "meta"."subform_slot"."id" IS 'Identifier of the row; what Meta<subform_slot> refers to.';
COMMENT ON COLUMN "meta"."subform_slot"."qualified_name" IS 'form.subform.';
COMMENT ON COLUMN "meta"."subform_slot"."form" IS 'The form.';
COMMENT ON COLUMN "meta"."subform_slot"."name" IS 'The sub-form slot''s name.';
COMMENT ON COLUMN "meta"."subform_slot"."position" IS 'Position among the form''s sub-form slots, from 1.';
COMMENT ON COLUMN "meta"."subform_slot"."accepts" IS 'The contract a chosen sub-form implements.';
COMMENT ON COLUMN "meta"."subform_slot"."multiplicity" IS 'one, optional or many.';
COMMENT ON COLUMN "meta"."subform_slot"."per" IS 'model or subject: what a choice is made for.';
COMMENT ON COLUMN "meta"."subform_slot"."doc" IS 'What the sub-form is.';

CREATE TABLE "meta"."entity" (
    "kind" text NOT NULL,
    "name" text NOT NULL,
    "id" uuid NOT NULL,
    "doc" text NOT NULL,
    CONSTRAINT "entity__pk" PRIMARY KEY ("kind", "name"),
    CONSTRAINT "entity__uq__id" UNIQUE ("id")
);
COMMENT ON TABLE "meta"."entity" IS 'A declared entity: an instance the declaration itself asserts.';
COMMENT ON COLUMN "meta"."entity"."kind" IS 'The entity''s kind.';
COMMENT ON COLUMN "meta"."entity"."name" IS 'The declared name.';
COMMENT ON COLUMN "meta"."entity"."id" IS 'The deterministic identifier of the instance.';
COMMENT ON COLUMN "meta"."entity"."doc" IS 'What the entity is.';

CREATE TABLE "meta"."trace" (
    "construct" text NOT NULL,
    "trace" text NOT NULL,
    CONSTRAINT "trace__pk" PRIMARY KEY ("construct", "trace")
);
COMMENT ON TABLE "meta"."trace" IS 'A handoff dictionary identifier a construct traces to.';
COMMENT ON COLUMN "meta"."trace"."construct" IS 'The construct path, e.g. kinds.species.attributes.charge.';
COMMENT ON COLUMN "meta"."trace"."trace" IS 'The identifier, e.g. IC-13.';

CREATE TABLE "meta"."pse_mark" (
    "construct" text NOT NULL,
    "mark" text NOT NULL,
    CONSTRAINT "pse_mark__pk" PRIMARY KEY ("construct")
);
COMMENT ON TABLE "meta"."pse_mark" IS 'A construct the .pse language cannot express today.';
COMMENT ON COLUMN "meta"."pse_mark"."construct" IS 'The construct path.';
COMMENT ON COLUMN "meta"."pse_mark"."mark" IS 'gap:<short name>.';

CREATE TABLE "prov"."record" (
    "id" uuid NOT NULL,
    "kind" text NOT NULL,
    CONSTRAINT "record__pk" PRIMARY KEY ("id")
);
COMMENT ON TABLE "prov"."record" IS 'Registry of every record: what a source asserted. Provenance attaches here.';
COMMENT ON COLUMN "prov"."record"."id" IS 'Identifier of the registered kind instance or relation row.';
COMMENT ON COLUMN "prov"."record"."kind" IS 'The name of the kind or relation the record is an instance of.';

CREATE TABLE "tk"."aggregation" (
    "id" uuid NOT NULL,
    "name" text NOT NULL,
    CONSTRAINT "aggregation__pk" PRIMARY KEY ("id"),
    CONSTRAINT "aggregation__identity" UNIQUE ("name")
);
COMMENT ON TABLE "tk"."aggregation" IS 'A state of aggregation. `aqueous` is deliberately not one: it is a liquid with a solvent convention.';
COMMENT ON COLUMN "tk"."aggregation"."id" IS 'Deterministic identifier of the aggregation instance.';
COMMENT ON COLUMN "tk"."aggregation"."name" IS 'Name of the state.';

CREATE TABLE "prov"."artifact" (
    "id" uuid NOT NULL,
    "carrier" uuid NOT NULL,
    "path" text NOT NULL,
    "sha256" "meta"."hash" NOT NULL,
    "size" bigint NOT NULL,
    CONSTRAINT "artifact__pk" PRIMARY KEY ("id"),
    CONSTRAINT "artifact__identity" UNIQUE ("carrier", "path"),
    CONSTRAINT "artifact__ck__size_nonnegative" CHECK ("size" >= 0)
);
COMMENT ON TABLE "prov"."artifact" IS 'One file within a carrier.';
COMMENT ON COLUMN "prov"."artifact"."id" IS 'Deterministic identifier of the artifact instance.';
COMMENT ON COLUMN "prov"."artifact"."carrier" IS 'The carrier the file belongs to.';
COMMENT ON COLUMN "prov"."artifact"."path" IS 'Path relative to the carrier''s tree.';
COMMENT ON COLUMN "prov"."artifact"."sha256" IS 'Content hash of the file.';
COMMENT ON COLUMN "prov"."artifact"."size" IS 'Size in bytes.';

CREATE TABLE "tk"."assembly_choice" (
    "id" uuid NOT NULL,
    "assembly" uuid NOT NULL,
    "path" text NOT NULL,
    "ordinal" bigint NOT NULL,
    "slot" uuid NOT NULL,
    "form" uuid NOT NULL,
    CONSTRAINT "assembly_choice__pk" PRIMARY KEY ("id"),
    CONSTRAINT "assembly_choice__identity" UNIQUE ("assembly", "path", "ordinal")
);
COMMENT ON TABLE "tk"."assembly_choice" IS 'The form an assembly puts in one sub-form slot. A slot with multiplicity many has several choices, ordered.';
COMMENT ON COLUMN "tk"."assembly_choice"."id" IS 'Deterministic identifier of the assembly_choice instance.';
COMMENT ON COLUMN "tk"."assembly_choice"."assembly" IS 'The assembly.';
COMMENT ON COLUMN "tk"."assembly_choice"."path" IS 'Path of sub-form slot names from the root to this slot.';
COMMENT ON COLUMN "tk"."assembly_choice"."ordinal" IS 'Position among the choices of a slot with multiplicity many; one otherwise.';
COMMENT ON COLUMN "tk"."assembly_choice"."slot" IS 'The sub-form slot filled.';
COMMENT ON COLUMN "tk"."assembly_choice"."form" IS 'The form chosen.';

CREATE TABLE "tk"."association_site" (
    "id" uuid NOT NULL,
    "scheme" uuid NOT NULL,
    "carrier_key" text NOT NULL,
    "label" text NOT NULL,
    "on_entity" uuid,
    "on_group" uuid,
    "multiplicity" "meta"."count" NOT NULL,
    CONSTRAINT "association_site__pk" PRIMARY KEY ("id"),
    CONSTRAINT "association_site__identity" UNIQUE ("scheme", "carrier_key", "label"),
    CONSTRAINT "association_site__ck__one_carrier" CHECK (num_nonnulls("on_entity", "on_group") = 1),
    CONSTRAINT "association_site__ck__multiplicity_nonnegative" CHECK ("multiplicity" >= 0)
);
COMMENT ON TABLE "tk"."association_site" IS 'A bonding site type on a species or a group under a site scheme.';
COMMENT ON COLUMN "tk"."association_site"."id" IS 'Deterministic identifier of the association_site instance.';
COMMENT ON COLUMN "tk"."association_site"."scheme" IS 'The site scheme.';
COMMENT ON COLUMN "tk"."association_site"."carrier_key" IS 'Identifier of the species or group that carries the site, as text, so the identity is one tuple for both cases.';
COMMENT ON COLUMN "tk"."association_site"."label" IS 'The site label, such as H or e.';
COMMENT ON COLUMN "tk"."association_site"."on_entity" IS 'The entity carrying the site.';
COMMENT ON COLUMN "tk"."association_site"."on_group" IS 'The group carrying the site.';
COMMENT ON COLUMN "tk"."association_site"."multiplicity" IS 'How many such sites the carrier has.';

CREATE TABLE "qual"."calculation" (
    "id" uuid NOT NULL,
    "key" text NOT NULL,
    "title" text NOT NULL,
    CONSTRAINT "calculation__pk" PRIMARY KEY ("id"),
    CONSTRAINT "calculation__identity" UNIQUE ("key")
);
COMMENT ON TABLE "qual"."calculation" IS 'A kind of calculation a thermodynamic library offers: a problem it solves, not a model form. Constrained Gibbs minimisation and phase stability are calculations.';
COMMENT ON COLUMN "qual"."calculation"."id" IS 'Deterministic identifier of the calculation instance.';
COMMENT ON COLUMN "qual"."calculation"."key" IS 'Stable key.';
COMMENT ON COLUMN "qual"."calculation"."title" IS 'Name of the calculation.';

CREATE TABLE "prov"."carrier" (
    "id" uuid NOT NULL,
    "manifest_id" text NOT NULL,
    "resolved_pin" text NOT NULL,
    "tree_hash" "meta"."hash" NOT NULL,
    "retrieved" timestamptz NOT NULL,
    CONSTRAINT "carrier__pk" PRIMARY KEY ("id")
);
COMMENT ON TABLE "prov"."carrier" IS 'One acquisition of one declared source at one resolved pin: the bytes that records were read from.';
COMMENT ON COLUMN "prov"."carrier"."id" IS 'Deterministic identifier of the carrier instance.';
COMMENT ON COLUMN "prov"."carrier"."manifest_id" IS 'The id of the source manifest.';
COMMENT ON COLUMN "prov"."carrier"."resolved_pin" IS 'The commit, DOI version or retrieval date that resolved.';
COMMENT ON COLUMN "prov"."carrier"."tree_hash" IS 'The lock''s tree hash of the acquired files.';
COMMENT ON COLUMN "prov"."carrier"."retrieved" IS 'When the bytes were acquired.';

CREATE TABLE "tk"."chemical_system" (
    "id" uuid NOT NULL,
    "key" text NOT NULL,
    "revision" text NOT NULL,
    CONSTRAINT "chemical_system__pk" PRIMARY KEY ("id"),
    CONSTRAINT "chemical_system__identity" UNIQUE ("key", "revision")
);
COMMENT ON TABLE "tk"."chemical_system" IS 'The species forms, phases, reactions and conserved quantities one source treats together. What a TDB or PHREEQC file calls a database is a chemical system plus a parameterisation plus a convention set.';
COMMENT ON COLUMN "tk"."chemical_system"."id" IS 'Deterministic identifier of the chemical_system instance.';
COMMENT ON COLUMN "tk"."chemical_system"."key" IS 'Stable key.';
COMMENT ON COLUMN "tk"."chemical_system"."revision" IS 'Revision of the system definition.';

CREATE TABLE "tk"."composition_basis" (
    "id" uuid NOT NULL,
    "name" text NOT NULL,
    "needs" text,
    CONSTRAINT "composition_basis__pk" PRIMARY KEY ("id"),
    CONSTRAINT "composition_basis__identity" UNIQUE ("name")
);
COMMENT ON TABLE "tk"."composition_basis" IS 'What a composition vector means: the kind of fraction or concentration and what it is measured against. Converting between bases names the data it needs.';
COMMENT ON COLUMN "tk"."composition_basis"."id" IS 'Deterministic identifier of the composition_basis instance.';
COMMENT ON COLUMN "tk"."composition_basis"."name" IS 'Name of the basis.';
COMMENT ON COLUMN "tk"."composition_basis"."needs" IS 'Auxiliary data a conversion to mole fractions needs.';

CREATE TABLE "tk"."conserved_quantity" (
    "id" uuid NOT NULL,
    "key" text NOT NULL,
    "kind" "meta"."conserved_kind" NOT NULL,
    CONSTRAINT "conserved_quantity__pk" PRIMARY KEY ("id"),
    CONSTRAINT "conserved_quantity__identity" UNIQUE ("key")
);
COMMENT ON TABLE "tk"."conserved_quantity" IS 'Anything a formula matrix conserves. A balance may be claimed only over declared quantities.';
COMMENT ON COLUMN "tk"."conserved_quantity"."id" IS 'Deterministic identifier of the conserved_quantity instance.';
COMMENT ON COLUMN "tk"."conserved_quantity"."key" IS 'Element symbol, `charge`, or a site label qualified by its chemical system.';
COMMENT ON COLUMN "tk"."conserved_quantity"."kind" IS 'What kind of quantity it is.';

CREATE TABLE "tk"."constituent_array" (
    "id" uuid NOT NULL,
    "phase" uuid NOT NULL,
    "canonical_key" text NOT NULL,
    CONSTRAINT "constituent_array__pk" PRIMARY KEY ("id"),
    CONSTRAINT "constituent_array__identity" UNIQUE ("phase", "canonical_key")
);
COMMENT ON TABLE "tk"."constituent_array" IS 'A choice of one or more species on each site class of a phase, in a stated order: the subject of a compound-energy parameter. The order of interacting species on a site class fixes the sign of odd-order interaction terms and which species a ternary index selects, so it is part of the array. Canonical key: the phase and, per site class in order, the species in position order as the source asserted them. Two arrays that differ only in that order are different arrays; that they describe one physical array is an equivalence assessment, not part of identity.';
COMMENT ON COLUMN "tk"."constituent_array"."id" IS 'Deterministic identifier of the constituent_array instance.';
COMMENT ON COLUMN "tk"."constituent_array"."phase" IS 'The phase.';
COMMENT ON COLUMN "tk"."constituent_array"."canonical_key" IS 'The canonical encoding of the array.';

CREATE TABLE "tk"."convention_set" (
    "id" uuid NOT NULL,
    "key" text NOT NULL,
    "revision" text NOT NULL,
    "energy_reference" uuid,
    "gas_constant" "meta"."gas_constant",
    "temperature_scale" "meta"."temperature_scale" NOT NULL,
    "atomic_weights" uuid,
    CONSTRAINT "convention_set__pk" PRIMARY KEY ("id"),
    CONSTRAINT "convention_set__identity" UNIQUE ("key", "revision")
);
COMMENT ON TABLE "tk"."convention_set" IS 'The conventions one coherent body of data assumes. A transformation between two convention sets is a scoped function with evidence, never a scalar offset.';
COMMENT ON COLUMN "tk"."convention_set"."id" IS 'Deterministic identifier of the convention_set instance.';
COMMENT ON COLUMN "tk"."convention_set"."key" IS 'Stable key.';
COMMENT ON COLUMN "tk"."convention_set"."revision" IS 'Revision.';
COMMENT ON COLUMN "tk"."convention_set"."energy_reference" IS 'The energy reference, for data that carry absolute or formation energies.';
COMMENT ON COLUMN "tk"."convention_set"."gas_constant" IS 'The value of the gas constant the data was built with.';
COMMENT ON COLUMN "tk"."convention_set"."temperature_scale" IS 'The temperature scale.';
COMMENT ON COLUMN "tk"."convention_set"."atomic_weights" IS 'The atomic-weight edition.';

CREATE TABLE "ev"."data_point" (
    "id" uuid NOT NULL,
    "dataset" uuid NOT NULL,
    "index" bigint NOT NULL,
    "branch" "meta"."branch" NOT NULL DEFAULT 'not_applicable',
    CONSTRAINT "data_point__pk" PRIMARY KEY ("id"),
    CONSTRAINT "data_point__identity" UNIQUE ("dataset", "index")
);
COMMENT ON TABLE "ev"."data_point" IS 'One row of a dataset.';
COMMENT ON COLUMN "ev"."data_point"."id" IS 'Deterministic identifier of the data_point instance.';
COMMENT ON COLUMN "ev"."data_point"."dataset" IS 'The dataset.';
COMMENT ON COLUMN "ev"."data_point"."index" IS 'Position of the point, from one.';
COMMENT ON COLUMN "ev"."data_point"."branch" IS 'The branch of a path-dependent measurement.';

CREATE TABLE "ev"."dataset" (
    "id" uuid NOT NULL,
    "carrier" uuid NOT NULL,
    "local_key" text NOT NULL,
    "kind" "meta"."dataset_kind" NOT NULL,
    "title" text,
    "method" text,
    "convention_set" uuid,
    "reaction" uuid,
    "verifies" uuid,
    CONSTRAINT "dataset__pk" PRIMARY KEY ("id"),
    CONSTRAINT "dataset__identity" UNIQUE ("carrier", "local_key")
);
COMMENT ON TABLE "ev"."dataset" IS 'A table of observations or evaluated values under declared conditions, from one carrier.';
COMMENT ON COLUMN "ev"."dataset"."id" IS 'Deterministic identifier of the dataset instance.';
COMMENT ON COLUMN "ev"."dataset"."carrier" IS 'The carrier the dataset was read from.';
COMMENT ON COLUMN "ev"."dataset"."local_key" IS 'The dataset''s key within that carrier.';
COMMENT ON COLUMN "ev"."dataset"."kind" IS 'What its values are.';
COMMENT ON COLUMN "ev"."dataset"."title" IS 'Title or description as the source gives it.';
COMMENT ON COLUMN "ev"."dataset"."method" IS 'Experimental or evaluation method as the source names it.';
COMMENT ON COLUMN "ev"."dataset"."convention_set" IS 'The conventions its values assume, where the dataset reports reference-dependent quantities.';
COMMENT ON COLUMN "ev"."dataset"."reaction" IS 'The reaction, for a dataset of reaction properties.';
COMMENT ON COLUMN "ev"."dataset"."verifies" IS 'For a verification dataset: the model assembly or parameterisation whose implementation its values check.';

CREATE TABLE "ev"."dataset_column" (
    "id" uuid NOT NULL,
    "dataset" uuid NOT NULL,
    "ordinal" bigint NOT NULL,
    "role" "meta"."column_role" NOT NULL,
    "observable" uuid NOT NULL,
    "component" uuid,
    "phase" uuid,
    "second_phase" uuid,
    "composition_basis" uuid,
    "standard_state" uuid,
    "constant" "meta"."finite_real",
    "source_name" text,
    CONSTRAINT "dataset_column__pk" PRIMARY KEY ("id"),
    CONSTRAINT "dataset_column__identity" UNIQUE ("dataset", "ordinal")
);
COMMENT ON TABLE "ev"."dataset_column" IS 'One typed column of a dataset.';
COMMENT ON COLUMN "ev"."dataset_column"."id" IS 'Deterministic identifier of the dataset_column instance.';
COMMENT ON COLUMN "ev"."dataset_column"."dataset" IS 'The dataset.';
COMMENT ON COLUMN "ev"."dataset_column"."ordinal" IS 'Position of the column, from one.';
COMMENT ON COLUMN "ev"."dataset_column"."role" IS 'The part it plays.';
COMMENT ON COLUMN "ev"."dataset_column"."observable" IS 'What its values are; values are stored in the observable''s storage unit.';
COMMENT ON COLUMN "ev"."dataset_column"."component" IS 'The component the column refers to, where the observable is of a component.';
COMMENT ON COLUMN "ev"."dataset_column"."phase" IS 'The phase the column refers to.';
COMMENT ON COLUMN "ev"."dataset_column"."second_phase" IS 'The other phase, for a transition or interface observable.';
COMMENT ON COLUMN "ev"."dataset_column"."composition_basis" IS 'The basis, for a composition column.';
COMMENT ON COLUMN "ev"."dataset_column"."standard_state" IS 'The standard state, for a standard-state observable.';
COMMENT ON COLUMN "ev"."dataset_column"."constant" IS 'The value of a constraint column, in the observable''s storage unit.';
COMMENT ON COLUMN "ev"."dataset_column"."source_name" IS 'The column''s name or property string in the source. Retained; nothing branches on it.';

CREATE TABLE "ev"."dataset_component" (
    "id" uuid NOT NULL,
    "dataset" uuid NOT NULL,
    "ordinal" bigint NOT NULL,
    "entity" uuid NOT NULL,
    "sample" uuid,
    "function" "meta"."component_function" NOT NULL,
    CONSTRAINT "dataset_component__pk" PRIMARY KEY ("id"),
    CONSTRAINT "dataset_component__identity" UNIQUE ("dataset", "ordinal")
);
COMMENT ON TABLE "ev"."dataset_component" IS 'An entity present in the system a dataset describes.';
COMMENT ON COLUMN "ev"."dataset_component"."id" IS 'Deterministic identifier of the dataset_component instance.';
COMMENT ON COLUMN "ev"."dataset_component"."dataset" IS 'The dataset.';
COMMENT ON COLUMN "ev"."dataset_component"."ordinal" IS 'Position of the component in the dataset, from one.';
COMMENT ON COLUMN "ev"."dataset_component"."entity" IS 'The entity.';
COMMENT ON COLUMN "ev"."dataset_component"."sample" IS 'The physical sample used.';
COMMENT ON COLUMN "ev"."dataset_component"."function" IS 'The part it plays.';

CREATE TABLE "ev"."dataset_phase" (
    "id" uuid NOT NULL,
    "dataset" uuid NOT NULL,
    "ordinal" bigint NOT NULL,
    "aggregation" uuid NOT NULL,
    "label" text,
    CONSTRAINT "dataset_phase__pk" PRIMARY KEY ("id"),
    CONSTRAINT "dataset_phase__identity" UNIQUE ("dataset", "ordinal")
);
COMMENT ON TABLE "ev"."dataset_phase" IS 'A phase role local to a dataset, such as the liquid in equilibrium with a vapour. It is not a phase definition and has no meaning outside its dataset.';
COMMENT ON COLUMN "ev"."dataset_phase"."id" IS 'Deterministic identifier of the dataset_phase instance.';
COMMENT ON COLUMN "ev"."dataset_phase"."dataset" IS 'The dataset.';
COMMENT ON COLUMN "ev"."dataset_phase"."ordinal" IS 'Position of the phase in the dataset, from one.';
COMMENT ON COLUMN "ev"."dataset_phase"."aggregation" IS 'Its state of aggregation.';
COMMENT ON COLUMN "ev"."dataset_phase"."label" IS 'The phase''s name in the source.';

CREATE TABLE "tk"."defined_mixture" (
    "id" uuid NOT NULL,
    "definition" "meta"."mixture_definition" NOT NULL,
    "mole_basis" boolean NOT NULL,
    CONSTRAINT "defined_mixture__pk" PRIMARY KEY ("id")
);
COMMENT ON TABLE "tk"."defined_mixture" IS 'A fixed-composition blend that sources treat as one entity, such as air, a refrigerant blend or normal hydrogen.';
COMMENT ON COLUMN "tk"."defined_mixture"."id" IS 'Deterministic identifier of the defined_mixture instance.';
COMMENT ON COLUMN "tk"."defined_mixture"."definition" IS 'Why the composition is fixed.';
COMMENT ON COLUMN "tk"."defined_mixture"."mole_basis" IS 'True when the component fractions are mole fractions, false for mass fractions.';

CREATE TABLE "prov"."derivation" (
    "id" uuid NOT NULL,
    "key" text NOT NULL,
    "kind" "meta"."derivation_kind" NOT NULL,
    "method" text,
    "software" uuid,
    CONSTRAINT "derivation__pk" PRIMARY KEY ("id"),
    CONSTRAINT "derivation__identity" UNIQUE ("key")
);
COMMENT ON TABLE "prov"."derivation" IS 'An activity that produced records from other records. Lineage is acyclic.';
COMMENT ON COLUMN "prov"."derivation"."id" IS 'Deterministic identifier of the derivation instance.';
COMMENT ON COLUMN "prov"."derivation"."key" IS 'Stable key assigned by the mapping that records the derivation.';
COMMENT ON COLUMN "prov"."derivation"."kind" IS 'What kind of activity it was.';
COMMENT ON COLUMN "prov"."derivation"."method" IS 'Name of the method, rule or recipe.';
COMMENT ON COLUMN "prov"."derivation"."software" IS 'The software that performed it, where known.';

CREATE TABLE "tk"."distributed_attribute" (
    "id" uuid NOT NULL,
    "key" text NOT NULL,
    "support" uuid NOT NULL,
    "weighting" "meta"."weighting" NOT NULL,
    "density" boolean NOT NULL,
    CONSTRAINT "distributed_attribute__pk" PRIMARY KEY ("id"),
    CONSTRAINT "distributed_attribute__identity" UNIQUE ("key")
);
COMMENT ON TABLE "tk"."distributed_attribute" IS 'The meaning of a distribution attached to material: what it is distributed over, how it is weighted and how it is normalised.';
COMMENT ON COLUMN "tk"."distributed_attribute"."id" IS 'Deterministic identifier of the distributed_attribute instance.';
COMMENT ON COLUMN "tk"."distributed_attribute"."key" IS 'Stable key.';
COMMENT ON COLUMN "tk"."distributed_attribute"."support" IS 'The quantity type of the coordinate the distribution is over.';
COMMENT ON COLUMN "tk"."distributed_attribute"."weighting" IS 'How it is weighted.';
COMMENT ON COLUMN "tk"."distributed_attribute"."density" IS 'True for a density over the support, false for weights in bins.';

CREATE TABLE "tk"."element" (
    "id" uuid NOT NULL,
    "atomic_number" bigint NOT NULL,
    "symbol" text NOT NULL,
    CONSTRAINT "element__pk" PRIMARY KEY ("id"),
    CONSTRAINT "element__uq__atomic_number" UNIQUE ("atomic_number"),
    CONSTRAINT "element__uq__symbol" UNIQUE ("symbol"),
    CONSTRAINT "element__ck__atomic_number_positive" CHECK ("atomic_number" > 0)
);
COMMENT ON TABLE "tk"."element" IS 'A chemical element. Its standard atomic weight belongs to an atomic-weight edition, not to the element.';
COMMENT ON COLUMN "tk"."element"."id" IS 'Deterministic identifier of the element instance.';
COMMENT ON COLUMN "tk"."element"."atomic_number" IS 'Atomic number.';
COMMENT ON COLUMN "tk"."element"."symbol" IS 'Element symbol.';

CREATE TABLE "tk"."energy_reference" (
    "id" uuid NOT NULL,
    "key" text NOT NULL,
    "enthalpy" "meta"."enthalpy_datum" NOT NULL,
    "entropy" "meta"."entropy_datum" NOT NULL,
    "temperature" "meta"."temperature",
    "pressure" "meta"."pressure",
    "state" text,
    CONSTRAINT "energy_reference__pk" PRIMARY KEY ("id"),
    CONSTRAINT "energy_reference__identity" UNIQUE ("key")
);
COMMENT ON TABLE "tk"."energy_reference" IS 'The zero of enthalpy and of entropy for a body of data.';
COMMENT ON COLUMN "tk"."energy_reference"."id" IS 'Deterministic identifier of the energy_reference instance.';
COMMENT ON COLUMN "tk"."energy_reference"."key" IS 'Stable key.';
COMMENT ON COLUMN "tk"."energy_reference"."enthalpy" IS 'What fixes the zero of enthalpy.';
COMMENT ON COLUMN "tk"."energy_reference"."entropy" IS 'What fixes the zero of entropy.';
COMMENT ON COLUMN "tk"."energy_reference"."temperature" IS 'Reference temperature of the datum.';
COMMENT ON COLUMN "tk"."energy_reference"."pressure" IS 'Reference pressure of the datum.';
COMMENT ON COLUMN "tk"."energy_reference"."state" IS 'The named state of a zero-at-state datum, as the source describes it.';

CREATE TABLE "tk"."envelope" (
    "id" uuid NOT NULL,
    "parameter_set" uuid NOT NULL,
    "axis" uuid NOT NULL,
    "kind" "meta"."envelope_kind" NOT NULL,
    "lower" "meta"."finite_real",
    "upper" "meta"."finite_real",
    CONSTRAINT "envelope__pk" PRIMARY KEY ("id"),
    CONSTRAINT "envelope__identity" UNIQUE ("parameter_set", "axis", "kind"),
    CONSTRAINT "envelope__ck__bounds_ordered" CHECK ("lower" <= "upper")
);
COMMENT ON TABLE "tk"."envelope" IS 'Where a parameter set applies, along one observable. This is scientific applicability; it is not a numerical bound and not a piece interval.';
COMMENT ON COLUMN "tk"."envelope"."id" IS 'Deterministic identifier of the envelope instance.';
COMMENT ON COLUMN "tk"."envelope"."parameter_set" IS 'The set.';
COMMENT ON COLUMN "tk"."envelope"."axis" IS 'The observable the range is along.';
COMMENT ON COLUMN "tk"."envelope"."kind" IS 'What the range represents.';
COMMENT ON COLUMN "tk"."envelope"."lower" IS 'Lower bound in the axis observable''s storage unit; absent when unbounded below.';
COMMENT ON COLUMN "tk"."envelope"."upper" IS 'Upper bound in the axis observable''s storage unit; absent when unbounded above.';

CREATE TABLE "prov"."fit" (
    "id" uuid NOT NULL,
    "objective" text,
    "outcome" "meta"."fit_outcome" NOT NULL,
    CONSTRAINT "fit__pk" PRIMARY KEY ("id")
);
COMMENT ON TABLE "prov"."fit" IS 'A regression of parameters against evidence. A failed fit produces no selected parameter set.';
COMMENT ON COLUMN "prov"."fit"."id" IS 'Deterministic identifier of the fit instance.';
COMMENT ON COLUMN "prov"."fit"."objective" IS 'The objective function as the source describes it.';
COMMENT ON COLUMN "prov"."fit"."outcome" IS 'How the fit ended.';

CREATE TABLE "tk"."group" (
    "id" uuid NOT NULL,
    "scheme" uuid NOT NULL,
    "label" text NOT NULL,
    "role" "meta"."group_role" NOT NULL,
    "partition_class" uuid,
    "parent" uuid,
    "position" bigint,
    "pattern" text,
    CONSTRAINT "group__pk" PRIMARY KEY ("id"),
    CONSTRAINT "group__identity" UNIQUE ("scheme", "label")
);
COMMENT ON TABLE "tk"."group" IS 'A structural fragment, or a class of fragments, within a scheme.';
COMMENT ON COLUMN "tk"."group"."id" IS 'Deterministic identifier of the group instance.';
COMMENT ON COLUMN "tk"."group"."scheme" IS 'The scheme the group belongs to.';
COMMENT ON COLUMN "tk"."group"."label" IS 'The group''s label in that scheme.';
COMMENT ON COLUMN "tk"."group"."role" IS 'Fragment or partition class.';
COMMENT ON COLUMN "tk"."group"."partition_class" IS 'The class this fragment belongs to, such as its main group.';
COMMENT ON COLUMN "tk"."group"."parent" IS 'The parent node in a hierarchical scheme.';
COMMENT ON COLUMN "tk"."group"."position" IS 'Position among the children of its parent, from one. Matching descends to the first child that matches, so sibling order is part of the scheme.';
COMMENT ON COLUMN "tk"."group"."pattern" IS 'The structural pattern in the source''s own pattern language. Retained; nothing branches on it.';

CREATE TABLE "tk"."group_assignment" (
    "id" uuid NOT NULL,
    "entity" uuid NOT NULL,
    "scheme" uuid NOT NULL,
    "asserted_by" uuid NOT NULL,
    "origin" "meta"."assignment_origin" NOT NULL,
    CONSTRAINT "group_assignment__pk" PRIMARY KEY ("id"),
    CONSTRAINT "group_assignment__identity" UNIQUE ("entity", "scheme", "asserted_by")
);
COMMENT ON TABLE "tk"."group_assignment" IS 'One source''s decomposition of an entity into the groups of a scheme. Competing decompositions coexist.';
COMMENT ON COLUMN "tk"."group_assignment"."id" IS 'Deterministic identifier of the group_assignment instance.';
COMMENT ON COLUMN "tk"."group_assignment"."entity" IS 'The entity decomposed.';
COMMENT ON COLUMN "tk"."group_assignment"."scheme" IS 'The scheme used.';
COMMENT ON COLUMN "tk"."group_assignment"."asserted_by" IS 'The carrier that states the decomposition.';
COMMENT ON COLUMN "tk"."group_assignment"."origin" IS 'How it was obtained.';

CREATE TABLE "tk"."group_scheme" (
    "id" uuid NOT NULL,
    "key" text NOT NULL,
    "revision" text NOT NULL,
    "role" "meta"."group_scheme_role" NOT NULL,
    "dataless_rule" "meta"."dataless_node_rule" NOT NULL DEFAULT 'not_applicable',
    CONSTRAINT "group_scheme__pk" PRIMARY KEY ("id"),
    CONSTRAINT "group_scheme__identity" UNIQUE ("key", "revision")
);
COMMENT ON TABLE "tk"."group_scheme" IS 'One published way of cutting molecules into groups, at one revision. Groups, partitions and assignments are scoped to it.';
COMMENT ON COLUMN "tk"."group_scheme"."id" IS 'Deterministic identifier of the group_scheme instance.';
COMMENT ON COLUMN "tk"."group_scheme"."key" IS 'Stable key of the scheme.';
COMMENT ON COLUMN "tk"."group_scheme"."revision" IS 'Revision or publication year.';
COMMENT ON COLUMN "tk"."group_scheme"."role" IS 'What its groups are used for.';
COMMENT ON COLUMN "tk"."group_scheme"."dataless_rule" IS 'What an estimator does at a node that holds no data.';

CREATE TABLE "qual"."held_row" (
    "id" uuid NOT NULL,
    "manifest_id" text NOT NULL,
    "source_table" text NOT NULL,
    "locator" text NOT NULL,
    "state" "meta"."row_state" NOT NULL,
    "reason" "meta"."held_reason" NOT NULL,
    "detail" text NOT NULL,
    CONSTRAINT "held_row__pk" PRIMARY KEY ("id"),
    CONSTRAINT "held_row__identity" UNIQUE ("manifest_id", "source_table", "locator")
);
COMMENT ON TABLE "qual"."held_row" IS 'A source-faithful row that was not loaded, with the reason.';
COMMENT ON COLUMN "qual"."held_row"."id" IS 'Deterministic identifier of the held_row instance.';
COMMENT ON COLUMN "qual"."held_row"."manifest_id" IS 'The source.';
COMMENT ON COLUMN "qual"."held_row"."source_table" IS 'The source-faithful table.';
COMMENT ON COLUMN "qual"."held_row"."locator" IS 'The row''s locator.';
COMMENT ON COLUMN "qual"."held_row"."state" IS '`held` or `unmapped`.';
COMMENT ON COLUMN "qual"."held_row"."reason" IS 'Why it was not loaded.';
COMMENT ON COLUMN "qual"."held_row"."detail" IS 'The reason in words: what about this row led to it.';

CREATE TABLE "tk"."identity_assertion" (
    "id" uuid NOT NULL,
    "source_entity" uuid NOT NULL,
    "scheme" uuid NOT NULL,
    "value" text NOT NULL,
    CONSTRAINT "identity_assertion__pk" PRIMARY KEY ("id"),
    CONSTRAINT "identity_assertion__identity" UNIQUE ("source_entity", "scheme", "value"),
    CONSTRAINT "identity_assertion__ck__value_nonempty" CHECK ("value" <> '')
);
COMMENT ON TABLE "tk"."identity_assertion" IS 'One identifier or name a source gives for a source entity. The value is kept verbatim and is never parsed for meaning.';
COMMENT ON COLUMN "tk"."identity_assertion"."id" IS 'Deterministic identifier of the identity_assertion instance.';
COMMENT ON COLUMN "tk"."identity_assertion"."source_entity" IS 'The source entity the identifier is given for.';
COMMENT ON COLUMN "tk"."identity_assertion"."scheme" IS 'The naming scheme of the value.';
COMMENT ON COLUMN "tk"."identity_assertion"."value" IS 'The identifier or name, verbatim.';

CREATE TABLE "prov"."import_record" (
    "id" uuid NOT NULL,
    "artifact" uuid NOT NULL,
    "locator" text NOT NULL,
    "reader" text NOT NULL,
    "reader_version" text NOT NULL,
    CONSTRAINT "import_record__pk" PRIMARY KEY ("id"),
    CONSTRAINT "import_record__identity" UNIQUE ("artifact", "locator"),
    CONSTRAINT "import_record__ck__locator_nonempty" CHECK ("locator" <> '')
);
COMMENT ON TABLE "prov"."import_record" IS 'The statement that an artifact, at a locator, asserts something. It is the link from a canonical record back to the exact source bytes.';
COMMENT ON COLUMN "prov"."import_record"."id" IS 'Deterministic identifier of the import_record instance.';
COMMENT ON COLUMN "prov"."import_record"."artifact" IS 'The file the assertion was read from.';
COMMENT ON COLUMN "prov"."import_record"."locator" IS 'Position within the file: a row key, JSON pointer, line range or element path.';
COMMENT ON COLUMN "prov"."import_record"."reader" IS 'The reader that produced the source-faithful row.';
COMMENT ON COLUMN "prov"."import_record"."reader_version" IS 'Version of that reader.';

CREATE TABLE "prov"."licence" (
    "id" uuid NOT NULL,
    "key" text NOT NULL,
    "spdx" "meta"."id_spdx",
    "title" text NOT NULL,
    CONSTRAINT "licence__pk" PRIMARY KEY ("id"),
    CONSTRAINT "licence__identity" UNIQUE ("key")
);
COMMENT ON TABLE "prov"."licence" IS 'A named set of terms.';
COMMENT ON COLUMN "prov"."licence"."id" IS 'Deterministic identifier of the licence instance.';
COMMENT ON COLUMN "prov"."licence"."key" IS 'Stable key.';
COMMENT ON COLUMN "prov"."licence"."spdx" IS 'SPDX identifier where one exists.';
COMMENT ON COLUMN "prov"."licence"."title" IS 'Name of the terms.';

CREATE TABLE "qual"."mapping_coverage" (
    "id" uuid NOT NULL,
    "manifest_id" text NOT NULL,
    "source_table" text NOT NULL,
    "state" "meta"."row_state" NOT NULL,
    "rows" bigint NOT NULL,
    CONSTRAINT "mapping_coverage__pk" PRIMARY KEY ("id"),
    CONSTRAINT "mapping_coverage__identity" UNIQUE ("manifest_id", "source_table", "state"),
    CONSTRAINT "mapping_coverage__ck__rows_nonnegative" CHECK ("rows" >= 0)
);
COMMENT ON TABLE "qual"."mapping_coverage" IS 'How many rows of a source-faithful table ended in each state in one build.';
COMMENT ON COLUMN "qual"."mapping_coverage"."id" IS 'Deterministic identifier of the mapping_coverage instance.';
COMMENT ON COLUMN "qual"."mapping_coverage"."manifest_id" IS 'The source.';
COMMENT ON COLUMN "qual"."mapping_coverage"."source_table" IS 'The source-faithful table.';
COMMENT ON COLUMN "qual"."mapping_coverage"."state" IS 'The state.';
COMMENT ON COLUMN "qual"."mapping_coverage"."rows" IS 'Number of rows in that state.';

CREATE TABLE "qual"."mapping_rule" (
    "id" uuid NOT NULL,
    "manifest_id" text NOT NULL,
    "source_table" text NOT NULL,
    "source_field" text NOT NULL,
    "disposition" "meta"."table_disposition" NOT NULL,
    "target" text,
    "source_unit" text,
    "factor" "meta"."finite_real",
    "precision" "meta"."mapping_precision",
    "loss" text,
    "applied_rows" bigint,
    CONSTRAINT "mapping_rule__pk" PRIMARY KEY ("id"),
    CONSTRAINT "mapping_rule__identity" UNIQUE ("manifest_id", "source_table", "source_field")
);
COMMENT ON TABLE "qual"."mapping_rule" IS 'One declared rule of a mapping: a field of a source-faithful table and the canonical target it becomes, with the unit conversion applied and what the mapping loses or assumes.';
COMMENT ON COLUMN "qual"."mapping_rule"."id" IS 'Deterministic identifier of the mapping_rule instance.';
COMMENT ON COLUMN "qual"."mapping_rule"."manifest_id" IS 'The source the mapping is for.';
COMMENT ON COLUMN "qual"."mapping_rule"."source_table" IS 'The source-faithful table.';
COMMENT ON COLUMN "qual"."mapping_rule"."source_field" IS 'The field; empty for a rule about the table as a whole.';
COMMENT ON COLUMN "qual"."mapping_rule"."disposition" IS 'What the mapping does with the table.';
COMMENT ON COLUMN "qual"."mapping_rule"."target" IS 'The canonical target: a kind attribute, a relation value or a form.group.slot.';
COMMENT ON COLUMN "qual"."mapping_rule"."source_unit" IS 'The unit of the source values as the mapping declares it.';
COMMENT ON COLUMN "qual"."mapping_rule"."factor" IS 'The factor from the source unit to the target''s storage unit.';
COMMENT ON COLUMN "qual"."mapping_rule"."precision" IS 'How closely the source''s meaning matches the target.';
COMMENT ON COLUMN "qual"."mapping_rule"."loss" IS 'What the rule loses or assumes, or why the table is out of scope or deferred.';
COMMENT ON COLUMN "qual"."mapping_rule"."applied_rows" IS 'For a value rule, the number of mapped rows of its table the mapping applied it to, that is, rows for which it produced a value in a block that wrote records; absent for any other rule.';

CREATE TABLE "tk"."material" (
    "id" uuid NOT NULL,
    "registry_key" text,
    CONSTRAINT "material__pk" PRIMARY KEY ("id")
);
COMMENT ON TABLE "tk"."material" IS 'A solid host or adsorbent identified by a registry or name, not by composition.';
COMMENT ON COLUMN "tk"."material"."id" IS 'Deterministic identifier of the material instance.';
COMMENT ON COLUMN "tk"."material"."registry_key" IS 'The identifier in the registry that defines it.';

CREATE TABLE "tk"."material_entity" (
    "id" uuid NOT NULL,
    "canonical_key" text NOT NULL,
    "label" text NOT NULL,
    "provisional" boolean NOT NULL DEFAULT false,
    CONSTRAINT "material_entity__pk" PRIMARY KEY ("id"),
    CONSTRAINT "material_entity__identity" UNIQUE ("canonical_key")
);
COMMENT ON TABLE "tk"."material_entity" IS 'Anything a composition coordinate can index. It requires no formula, registry number or molar mass.';
COMMENT ON COLUMN "tk"."material_entity"."id" IS 'Deterministic identifier of the material_entity instance.';
COMMENT ON COLUMN "tk"."material_entity"."canonical_key" IS 'The identity value, computed by the rule of the refinement (see each refinement).';
COMMENT ON COLUMN "tk"."material_entity"."label" IS 'A preferred display name. Never identity.';
COMMENT ON COLUMN "tk"."material_entity"."provisional" IS 'True when the entity stands for one source entity that has not been identified with a canonical entity. Records about a provisional entity are usable within their carrier and are not joined across carriers.';

CREATE TABLE "tk"."member_role" (
    "id" uuid NOT NULL,
    "name" text NOT NULL,
    CONSTRAINT "member_role__pk" PRIMARY KEY ("id"),
    CONSTRAINT "member_role__identity" UNIQUE ("name")
);
COMMENT ON TABLE "tk"."member_role" IS 'The part a species form plays in the phases of a chemical system: the solvent or a solute of a solution, a pure phase, a gas, a surface or exchange species. A convention set gives the standard state of each role.';
COMMENT ON COLUMN "tk"."member_role"."id" IS 'Deterministic identifier of the member_role instance.';
COMMENT ON COLUMN "tk"."member_role"."name" IS 'Name of the role.';

CREATE TABLE "tk"."model_assembly" (
    "id" uuid NOT NULL,
    "key" text NOT NULL,
    "revision" text NOT NULL,
    "title" text NOT NULL,
    "root" uuid NOT NULL,
    CONSTRAINT "model_assembly__pk" PRIMARY KEY ("id"),
    CONSTRAINT "model_assembly__identity" UNIQUE ("key", "revision")
);
COMMENT ON TABLE "tk"."model_assembly" IS 'A tree of form choices with every sub-form slot decided: a complete model. Named models such as PSRK, GERG-2008 and IAPWS-IF97 are assemblies.';
COMMENT ON COLUMN "tk"."model_assembly"."id" IS 'Deterministic identifier of the model_assembly instance.';
COMMENT ON COLUMN "tk"."model_assembly"."key" IS 'Stable key.';
COMMENT ON COLUMN "tk"."model_assembly"."revision" IS 'Revision.';
COMMENT ON COLUMN "tk"."model_assembly"."title" IS 'Name by which the model is known.';
COMMENT ON COLUMN "tk"."model_assembly"."root" IS 'The form at the root of the tree.';

CREATE TABLE "tk"."model_component" (
    "id" uuid NOT NULL,
    "parameterization" uuid NOT NULL,
    "name" text NOT NULL,
    CONSTRAINT "model_component__pk" PRIMARY KEY ("id"),
    CONSTRAINT "model_component__identity" UNIQUE ("parameterization", "name")
);
COMMENT ON TABLE "tk"."model_component" IS 'A named component of a model that parameter sets share: a generalised departure function of a multifluid mixture model, a named function of temperature of a thermodynamic database. It is the subject of the parameter set that gives its values, and any number of other sets reference that set. Its name is scoped to a parameterisation.';
COMMENT ON COLUMN "tk"."model_component"."id" IS 'Deterministic identifier of the model_component instance.';
COMMENT ON COLUMN "tk"."model_component"."parameterization" IS 'The parameterisation the component''s name belongs to.';
COMMENT ON COLUMN "tk"."model_component"."name" IS 'The name the source gives the component.';

CREATE TABLE "tk"."naming_scheme" (
    "id" uuid NOT NULL,
    "name" text NOT NULL,
    "structural" boolean NOT NULL,
    "registry" boolean NOT NULL,
    CONSTRAINT "naming_scheme__pk" PRIMARY KEY ("id"),
    CONSTRAINT "naming_scheme__identity" UNIQUE ("name")
);
COMMENT ON TABLE "tk"."naming_scheme" IS 'A system of names or registry identifiers that sources use to refer to material: a registry, a structure notation, or a source''s own labels.';
COMMENT ON COLUMN "tk"."naming_scheme"."id" IS 'Deterministic identifier of the naming_scheme instance.';
COMMENT ON COLUMN "tk"."naming_scheme"."name" IS 'Name of the scheme.';
COMMENT ON COLUMN "tk"."naming_scheme"."structural" IS 'True when the value encodes chemical structure, so equal canonical values imply equal structure.';
COMMENT ON COLUMN "tk"."naming_scheme"."registry" IS 'True when the value is an entry in an external registry of substances, so that the corpus can cross-reference it to a structure.';

CREATE TABLE "param"."nasa7__pure" (
    "id" uuid NOT NULL,
    "slot_group" uuid NOT NULL DEFAULT '3ee2acab-9ebb-5ee6-9279-9e7968621ba1'::uuid,
    "i" uuid NOT NULL,
    CONSTRAINT "nasa7__pure__pk" PRIMARY KEY ("id"),
    CONSTRAINT "nasa7__pure__ck__slot_group" CHECK ("slot_group" = '3ee2acab-9ebb-5ee6-9279-9e7968621ba1'::uuid)
);
COMMENT ON TABLE "param"."nasa7__pure" IS 'The coefficient blocks of one species form.';
COMMENT ON COLUMN "param"."nasa7__pure"."id" IS 'Deterministic identifier of the nasa7__pure instance.';
COMMENT ON COLUMN "param"."nasa7__pure"."slot_group" IS 'The slot group of this table; fixed, and tied to the parameter set row.';
COMMENT ON COLUMN "param"."nasa7__pure"."i" IS 'The species form.';

CREATE TABLE "param"."nasa9__pure" (
    "id" uuid NOT NULL,
    "slot_group" uuid NOT NULL DEFAULT '07eb75cf-d58c-5939-a34a-c85cc14c0972'::uuid,
    "i" uuid NOT NULL,
    CONSTRAINT "nasa9__pure__pk" PRIMARY KEY ("id"),
    CONSTRAINT "nasa9__pure__ck__slot_group" CHECK ("slot_group" = '07eb75cf-d58c-5939-a34a-c85cc14c0972'::uuid)
);
COMMENT ON TABLE "param"."nasa9__pure" IS 'The coefficient blocks of one species form.';
COMMENT ON COLUMN "param"."nasa9__pure"."id" IS 'Deterministic identifier of the nasa9__pure instance.';
COMMENT ON COLUMN "param"."nasa9__pure"."slot_group" IS 'The slot group of this table; fixed, and tied to the parameter set row.';
COMMENT ON COLUMN "param"."nasa9__pure"."i" IS 'The species form.';

CREATE TABLE "tk"."observable" (
    "id" uuid NOT NULL,
    "key" text NOT NULL,
    "quantity" uuid NOT NULL,
    "subject" "meta"."subject_shape" NOT NULL,
    "basis" "meta"."amount_basis" NOT NULL,
    "relation" "meta"."reference_relation" NOT NULL,
    "path" "meta"."path" NOT NULL,
    "adsorption" "meta"."adsorption_kind" NOT NULL DEFAULT 'not_applicable',
    "diffusion" "meta"."diffusion_frame" NOT NULL DEFAULT 'not_applicable',
    CONSTRAINT "observable__pk" PRIMARY KEY ("id"),
    CONSTRAINT "observable__identity" UNIQUE ("key")
);
COMMENT ON TABLE "tk"."observable" IS 'A physical quantity with the facets needed to interpret a number for it.';
COMMENT ON COLUMN "tk"."observable"."id" IS 'Deterministic identifier of the observable instance.';
COMMENT ON COLUMN "tk"."observable"."key" IS 'Stable key.';
COMMENT ON COLUMN "tk"."observable"."quantity" IS 'The quantity type values are stored in.';
COMMENT ON COLUMN "tk"."observable"."subject" IS 'What it is a property of.';
COMMENT ON COLUMN "tk"."observable"."basis" IS 'What it is divided by.';
COMMENT ON COLUMN "tk"."observable"."relation" IS 'What it is relative to.';
COMMENT ON COLUMN "tk"."observable"."path" IS 'The path along which it is defined.';
COMMENT ON COLUMN "tk"."observable"."adsorption" IS 'Which adsorbed amount, for an adsorption observable.';
COMMENT ON COLUMN "tk"."observable"."diffusion" IS 'The frame of reference, for a diffusion observable.';

CREATE TABLE "tk"."observable_alias" (
    "id" uuid NOT NULL,
    "carrier_scope" text NOT NULL,
    "name" text NOT NULL,
    "observable" uuid NOT NULL,
    "precision" "meta"."mapping_precision" NOT NULL,
    "loss" text,
    CONSTRAINT "observable_alias__pk" PRIMARY KEY ("id"),
    CONSTRAINT "observable_alias__identity" UNIQUE ("carrier_scope", "name")
);
COMMENT ON TABLE "tk"."observable_alias" IS 'A source''s name for an observable. The mapping states its precision and what it loses.';
COMMENT ON COLUMN "tk"."observable_alias"."id" IS 'Deterministic identifier of the observable_alias instance.';
COMMENT ON COLUMN "tk"."observable_alias"."carrier_scope" IS 'The vocabulary the name belongs to, such as `thermoml` or `cape_open_1_1`.';
COMMENT ON COLUMN "tk"."observable_alias"."name" IS 'The name, verbatim.';
COMMENT ON COLUMN "tk"."observable_alias"."observable" IS 'The observable it denotes.';
COMMENT ON COLUMN "tk"."observable_alias"."precision" IS 'How closely the source''s meaning matches.';
COMMENT ON COLUMN "tk"."observable_alias"."loss" IS 'What the mapping loses or assumes, when it is not exact.';

CREATE TABLE "tk"."parameter_set" (
    "id" uuid NOT NULL,
    "parameterization" uuid NOT NULL,
    "slot_group" uuid NOT NULL,
    "subject_key" text NOT NULL,
    "occurrence" bigint NOT NULL DEFAULT 1,
    "parent" uuid,
    "parent_slot" uuid,
    CONSTRAINT "parameter_set__pk" PRIMARY KEY ("id"),
    CONSTRAINT "parameter_set__identity" UNIQUE ("parameterization", "slot_group", "subject_key", "occurrence"),
    CONSTRAINT "parameter_set__uq__id_slot_group" UNIQUE ("id", "slot_group")
);
COMMENT ON TABLE "tk"."parameter_set" IS 'One source''s coherent values for one slot group and one subject tuple, with its indexed children. Each slot group is a refinement of this kind.';
COMMENT ON COLUMN "tk"."parameter_set"."id" IS 'Deterministic identifier of the parameter_set instance.';
COMMENT ON COLUMN "tk"."parameter_set"."parameterization" IS 'The collection the set belongs to.';
COMMENT ON COLUMN "tk"."parameter_set"."slot_group" IS 'The slot group the set instantiates.';
COMMENT ON COLUMN "tk"."parameter_set"."subject_key" IS 'Canonical encoding of the subject identifiers in role order; for a nested set, the parent set, slot and index.';
COMMENT ON COLUMN "tk"."parameter_set"."occurrence" IS 'Distinguishes repeated assertions for one subject within one parameterisation, from one in source order. A source that lists a pair twice with different values has two sets; which one the source''s own code uses is a selection fact, not a reason to drop the other.';
COMMENT ON COLUMN "tk"."parameter_set"."parent" IS 'The set this one is a nested value of.';
COMMENT ON COLUMN "tk"."parameter_set"."parent_slot" IS 'The slot of the parent this set is the value of.';

CREATE TABLE "tk"."parameterization" (
    "id" uuid NOT NULL,
    "key" text NOT NULL,
    "revision" text NOT NULL,
    "title" text NOT NULL,
    "coherence" "meta"."coherence" NOT NULL,
    "convention_set" uuid,
    "site_scheme" uuid,
    "group_scheme" uuid,
    "chemical_system" uuid,
    "composition_basis" uuid,
    "reference_volume" "meta"."molar_volume",
    CONSTRAINT "parameterization__pk" PRIMARY KEY ("id"),
    CONSTRAINT "parameterization__identity" UNIQUE ("key", "revision")
);
COMMENT ON TABLE "tk"."parameterization" IS 'A published collection of parameter sets meant to be used together, under one convention set.';
COMMENT ON COLUMN "tk"."parameterization"."id" IS 'Deterministic identifier of the parameterization instance.';
COMMENT ON COLUMN "tk"."parameterization"."key" IS 'Stable key.';
COMMENT ON COLUMN "tk"."parameterization"."revision" IS 'Revision, publication year or carrier pin.';
COMMENT ON COLUMN "tk"."parameterization"."title" IS 'Name by which the collection is known.';
COMMENT ON COLUMN "tk"."parameterization"."coherence" IS 'How its sets relate to each other.';
COMMENT ON COLUMN "tk"."parameterization"."convention_set" IS 'The conventions its values assume.';
COMMENT ON COLUMN "tk"."parameterization"."site_scheme" IS 'The association site scheme its sets assume, where one applies.';
COMMENT ON COLUMN "tk"."parameterization"."group_scheme" IS 'The group scheme its sets are scoped to, where one applies.';
COMMENT ON COLUMN "tk"."parameterization"."chemical_system" IS 'The chemical system its sets belong to, where one applies.';
COMMENT ON COLUMN "tk"."parameterization"."composition_basis" IS 'The composition basis its interaction values assume, where the form leaves it open.';
COMMENT ON COLUMN "tk"."parameterization"."reference_volume" IS 'The reference volume its size ratios and interaction values are relative to, where the form leaves it open.';

CREATE TABLE "tk"."phase_definition" (
    "id" uuid NOT NULL,
    "system" uuid NOT NULL,
    "key" text NOT NULL,
    "aggregation" uuid NOT NULL,
    "structure" "meta"."phase_structure" NOT NULL,
    "prototype" text,
    "source_directives" text,
    CONSTRAINT "phase_definition__pk" PRIMARY KEY ("id"),
    CONSTRAINT "phase_definition__identity" UNIQUE ("system", "key")
);
COMMENT ON TABLE "tk"."phase_definition" IS 'A named solution or pure phase within a chemical system: its aggregation, constituents and internal structure.';
COMMENT ON COLUMN "tk"."phase_definition"."id" IS 'Deterministic identifier of the phase_definition instance.';
COMMENT ON COLUMN "tk"."phase_definition"."system" IS 'The system the phase belongs to.';
COMMENT ON COLUMN "tk"."phase_definition"."key" IS 'The phase''s name in that system.';
COMMENT ON COLUMN "tk"."phase_definition"."aggregation" IS 'Its state of aggregation.';
COMMENT ON COLUMN "tk"."phase_definition"."structure" IS 'The internal structure it assumes.';
COMMENT ON COLUMN "tk"."phase_definition"."prototype" IS 'A structure prototype or Strukturbericht designation, where the source gives one.';
COMMENT ON COLUMN "tk"."phase_definition"."source_directives" IS 'Uninterpreted source directives attached to the phase, retained verbatim.';

CREATE TABLE "tk"."polymer_type" (
    "id" uuid NOT NULL,
    "architecture" text,
    CONSTRAINT "polymer_type__pk" PRIMARY KEY ("id")
);
COMMENT ON TABLE "tk"."polymer_type" IS 'A polymer identified by its repeat units and architecture. A molar-mass distribution is a property of a sample or mixture, not of the type.';
COMMENT ON COLUMN "tk"."polymer_type"."id" IS 'Deterministic identifier of the polymer_type instance.';
COMMENT ON COLUMN "tk"."polymer_type"."architecture" IS 'Linear, branched, block and similar, as the source states it.';

CREATE TABLE "tk"."pseudo_component" (
    "id" uuid NOT NULL,
    "kind" "meta"."pseudo_component_kind" NOT NULL,
    "produced_by" uuid,
    CONSTRAINT "pseudo_component__pk" PRIMARY KEY ("id")
);
COMMENT ON TABLE "tk"."pseudo_component" IS 'An entity defined by characterisation or by fiat, without a formula. Its molar mass is asserted or estimated with provenance, never derived. Canonical key: the derivation that produced it and its index, or its own declared key.';
COMMENT ON COLUMN "tk"."pseudo_component"."id" IS 'Deterministic identifier of the pseudo_component instance.';
COMMENT ON COLUMN "tk"."pseudo_component"."kind" IS 'Why it has no formula.';
COMMENT ON COLUMN "tk"."pseudo_component"."produced_by" IS 'The characterisation that produced it.';

CREATE TABLE "prov"."publication" (
    "id" uuid NOT NULL,
    "doi" "meta"."id_doi",
    "isbn" "meta"."id_isbn",
    CONSTRAINT "publication__pk" PRIMARY KEY ("id"),
    CONSTRAINT "publication__uq__doi" UNIQUE ("doi")
);
COMMENT ON TABLE "prov"."publication" IS 'A published work that content is attributed to. Its identity is bound to the work: the key is `doi:` and the lower-case DOI when the work has one, so two carriers citing one paper under different citation keys name one publication, and otherwise `carrier:`, the citing carrier''s manifest id, `:` and its citation key. What a carrier says about the work (its citation key, year and citation text) is per carrier and lives on the `citation` relation, so carriers that differ in it still agree on the publication.';
COMMENT ON COLUMN "prov"."publication"."id" IS 'Deterministic identifier of the publication instance.';
COMMENT ON COLUMN "prov"."publication"."doi" IS 'The DOI in lower case, where one exists.';
COMMENT ON COLUMN "prov"."publication"."isbn" IS 'ISBN for a book.';

CREATE TABLE "qual"."qualification_run" (
    "id" uuid NOT NULL,
    "key" text NOT NULL,
    "form" uuid NOT NULL,
    "expression_hash" "meta"."hash" NOT NULL,
    "basis" "meta"."comparison_basis" NOT NULL,
    "reference" uuid,
    "outcome" "meta"."run_outcome" NOT NULL,
    "points" bigint NOT NULL,
    "relative_tolerance" "meta"."scalar" NOT NULL,
    "observable" uuid,
    "absolute_tolerance" "meta"."finite_real",
    "worst_relative_deviation" "meta"."scalar",
    "blocked_reason" "meta"."blocked_reason",
    "note" text,
    CONSTRAINT "qualification_run__pk" PRIMARY KEY ("id"),
    CONSTRAINT "qualification_run__identity" UNIQUE ("key"),
    CONSTRAINT "qualification_run__ck__blocked_reason_iff_blocked" CHECK (("blocked_reason" IS NOT NULL) = ("outcome"::text IN ('blocked')))
);
COMMENT ON TABLE "qual"."qualification_run" IS 'One comparison of a form, evaluated from canonical records, against an independent answer over a declared domain.';
COMMENT ON COLUMN "qual"."qualification_run"."id" IS 'Deterministic identifier of the qualification_run instance.';
COMMENT ON COLUMN "qual"."qualification_run"."key" IS 'Stable key: form, parameter set or sets, comparison basis and declaration fingerprint.';
COMMENT ON COLUMN "qual"."qualification_run"."form" IS 'The form evaluated.';
COMMENT ON COLUMN "qual"."qualification_run"."expression_hash" IS 'Hash of what evaluating the compared output reads from the form''s text (its locals, the output''s expression and its implicit blocks, canonically serialised): the run speaks for the form only while the form''s current hash in `meta.form_output.evaluation_hash` equals it.';
COMMENT ON COLUMN "qual"."qualification_run"."basis" IS 'What it was compared against.';
COMMENT ON COLUMN "qual"."qualification_run"."reference" IS 'The library release or publication that supplied the reference answers; absent for a run blocked before the reference was known.';
COMMENT ON COLUMN "qual"."qualification_run"."outcome" IS 'How the run ended.';
COMMENT ON COLUMN "qual"."qualification_run"."points" IS 'Number of points compared.';
COMMENT ON COLUMN "qual"."qualification_run"."relative_tolerance" IS 'Declared relative tolerance.';
COMMENT ON COLUMN "qual"."qualification_run"."observable" IS 'The observable of the contract output compared, where the output denotes one.';
COMMENT ON COLUMN "qual"."qualification_run"."absolute_tolerance" IS 'Declared absolute tolerance in the observable''s storage unit.';
COMMENT ON COLUMN "qual"."qualification_run"."worst_relative_deviation" IS 'Largest relative deviation observed.';
COMMENT ON COLUMN "qual"."qualification_run"."blocked_reason" IS 'Why a blocked run could not be carried out; present exactly when the outcome is `blocked`.';
COMMENT ON COLUMN "qual"."qualification_run"."note" IS 'The detail of a blocked run''s reason, or what the domain excluded.';

CREATE TABLE "tk"."reaction" (
    "id" uuid NOT NULL,
    "canonical_key" text NOT NULL,
    "extent" "meta"."extent_convention" NOT NULL,
    "equation" text,
    CONSTRAINT "reaction__pk" PRIMARY KEY ("id"),
    CONSTRAINT "reaction__identity" UNIQUE ("canonical_key")
);
COMMENT ON TABLE "tk"."reaction" IS 'A stoichiometry over species forms. Canonical key: the participants'' identifiers and coefficients in a normalised order, with the extent convention.';
COMMENT ON COLUMN "tk"."reaction"."id" IS 'Deterministic identifier of the reaction instance.';
COMMENT ON COLUMN "tk"."reaction"."canonical_key" IS 'Canonical encoding of the normalised stoichiometry.';
COMMENT ON COLUMN "tk"."reaction"."extent" IS 'How the stoichiometry is normalised.';
COMMENT ON COLUMN "tk"."reaction"."equation" IS 'The reaction as the source writes it. Retained; nothing branches on it.';

CREATE TABLE "tk"."resolved_snapshot" (
    "id" uuid NOT NULL,
    "key" text NOT NULL,
    "revision" text NOT NULL,
    "assembly" uuid NOT NULL,
    "policy" uuid NOT NULL,
    CONSTRAINT "resolved_snapshot__pk" PRIMARY KEY ("id"),
    CONSTRAINT "resolved_snapshot__identity" UNIQUE ("key", "revision")
);
COMMENT ON TABLE "tk"."resolved_snapshot" IS 'The frozen result of applying a selection policy to a model assembly and a set of entities: exactly one value per required slot and subject, every dependency satisfied or waived, conventions compatible, and no record whose rights forbid the use. It is the boundary between this open-world store and a closed-world package.';
COMMENT ON COLUMN "tk"."resolved_snapshot"."id" IS 'Deterministic identifier of the resolved_snapshot instance.';
COMMENT ON COLUMN "tk"."resolved_snapshot"."key" IS 'Stable key.';
COMMENT ON COLUMN "tk"."resolved_snapshot"."revision" IS 'Revision.';
COMMENT ON COLUMN "tk"."resolved_snapshot"."assembly" IS 'The model the snapshot resolves.';
COMMENT ON COLUMN "tk"."resolved_snapshot"."policy" IS 'The policy applied.';

CREATE TABLE "prov"."rights_determination" (
    "id" uuid NOT NULL,
    "carrier" uuid NOT NULL,
    "scope" text NOT NULL,
    "ordinal" bigint NOT NULL,
    "basis" "meta"."rights_basis" NOT NULL,
    "licence" uuid,
    "statement" text NOT NULL,
    "url" text,
    "store" "meta"."permission" NOT NULL,
    "redistribute" "meta"."permission" NOT NULL,
    "commercial" "meta"."permission" NOT NULL,
    "attribution_required" boolean NOT NULL,
    "share_alike" boolean NOT NULL,
    "observed" text NOT NULL,
    CONSTRAINT "rights_determination__pk" PRIMARY KEY ("id"),
    CONSTRAINT "rights_determination__identity" UNIQUE ("carrier", "scope", "ordinal")
);
COMMENT ON TABLE "prov"."rights_determination" IS 'A recorded claim about what may be done with part of a carrier. Competing claims about one scope are all kept; the model records claims and does not decide law.';
COMMENT ON COLUMN "prov"."rights_determination"."id" IS 'Deterministic identifier of the rights_determination instance.';
COMMENT ON COLUMN "prov"."rights_determination"."carrier" IS 'The carrier the claim concerns.';
COMMENT ON COLUMN "prov"."rights_determination"."scope" IS '`code`, `data`, or a path glob within the carrier.';
COMMENT ON COLUMN "prov"."rights_determination"."ordinal" IS 'Order among claims with the same carrier and scope.';
COMMENT ON COLUMN "prov"."rights_determination"."basis" IS 'What the claim rests on.';
COMMENT ON COLUMN "prov"."rights_determination"."licence" IS 'The licence, when the basis is a licence grant.';
COMMENT ON COLUMN "prov"."rights_determination"."statement" IS 'The governing statement, quoted or closely paraphrased.';
COMMENT ON COLUMN "prov"."rights_determination"."url" IS 'Where the statement was read.';
COMMENT ON COLUMN "prov"."rights_determination"."store" IS 'Keeping a local copy.';
COMMENT ON COLUMN "prov"."rights_determination"."redistribute" IS 'Passing the content on.';
COMMENT ON COLUMN "prov"."rights_determination"."commercial" IS 'Commercial use.';
COMMENT ON COLUMN "prov"."rights_determination"."attribution_required" IS 'Whether attribution is required.';
COMMENT ON COLUMN "prov"."rights_determination"."share_alike" IS 'Whether derived works must carry the same terms.';
COMMENT ON COLUMN "prov"."rights_determination"."observed" IS 'When and how the claim was established.';

CREATE TABLE "tk"."sample" (
    "id" uuid NOT NULL,
    "carrier" uuid NOT NULL,
    "local_key" text NOT NULL,
    "entity" uuid NOT NULL,
    "purity" "meta"."fraction",
    "purity_basis" "meta"."purity_basis" NOT NULL,
    "supplier" text,
    CONSTRAINT "sample__pk" PRIMARY KEY ("id"),
    CONSTRAINT "sample__identity" UNIQUE ("carrier", "local_key")
);
COMMENT ON TABLE "tk"."sample" IS 'A physical batch of an entity as used in a measurement.';
COMMENT ON COLUMN "tk"."sample"."id" IS 'Deterministic identifier of the sample instance.';
COMMENT ON COLUMN "tk"."sample"."carrier" IS 'The carrier that describes the sample.';
COMMENT ON COLUMN "tk"."sample"."local_key" IS 'The sample''s key within that carrier.';
COMMENT ON COLUMN "tk"."sample"."entity" IS 'What the sample is a batch of.';
COMMENT ON COLUMN "tk"."sample"."purity" IS 'Final stated purity.';
COMMENT ON COLUMN "tk"."sample"."purity_basis" IS 'Basis of the stated purity.';
COMMENT ON COLUMN "tk"."sample"."supplier" IS 'Where the sample came from.';

CREATE TABLE "tk"."selection_policy" (
    "id" uuid NOT NULL,
    "key" text NOT NULL,
    "revision" text NOT NULL,
    "unasserted" "meta"."unasserted_policy" NOT NULL,
    "rule" text,
    "asserted_by" uuid,
    "scope_slot_group" uuid,
    "scope_observable" uuid,
    "as_documented" boolean,
    CONSTRAINT "selection_policy__pk" PRIMARY KEY ("id"),
    CONSTRAINT "selection_policy__identity" UNIQUE ("key", "revision")
);
COMMENT ON TABLE "tk"."selection_policy" IS 'An ordered preference among parameterisations, with per-subject overrides and a stated behaviour when nothing is asserted. Applying it is deterministic.';
COMMENT ON COLUMN "tk"."selection_policy"."id" IS 'Deterministic identifier of the selection_policy instance.';
COMMENT ON COLUMN "tk"."selection_policy"."key" IS 'Stable key.';
COMMENT ON COLUMN "tk"."selection_policy"."revision" IS 'Revision.';
COMMENT ON COLUMN "tk"."selection_policy"."unasserted" IS 'What to do when no set is asserted for a required subject.';
COMMENT ON COLUMN "tk"."selection_policy"."rule" IS 'The named rule or stated default, when the policy uses one.';
COMMENT ON COLUMN "tk"."selection_policy"."asserted_by" IS 'The carrier whose own default behaviour this policy records; absent for a policy authored for a snapshot.';
COMMENT ON COLUMN "tk"."selection_policy"."scope_slot_group" IS 'The slot group the policy governs, when it is narrower than everything.';
COMMENT ON COLUMN "tk"."selection_policy"."scope_observable" IS 'The observable the policy governs, when it is narrower than everything.';
COMMENT ON COLUMN "tk"."selection_policy"."as_documented" IS 'For a carrier''s policy: whether the behaviour recorded matches what the carrier documents.';

CREATE TABLE "param"."shomate__pure" (
    "id" uuid NOT NULL,
    "slot_group" uuid NOT NULL DEFAULT '57160327-fa37-51f8-9549-02af8691b569'::uuid,
    "i" uuid NOT NULL,
    CONSTRAINT "shomate__pure__pk" PRIMARY KEY ("id"),
    CONSTRAINT "shomate__pure__ck__slot_group" CHECK ("slot_group" = '57160327-fa37-51f8-9549-02af8691b569'::uuid)
);
COMMENT ON TABLE "param"."shomate__pure" IS 'The coefficient blocks of one species form.';
COMMENT ON COLUMN "param"."shomate__pure"."id" IS 'Deterministic identifier of the shomate__pure instance.';
COMMENT ON COLUMN "param"."shomate__pure"."slot_group" IS 'The slot group of this table; fixed, and tied to the parameter set row.';
COMMENT ON COLUMN "param"."shomate__pure"."i" IS 'The species form.';

CREATE TABLE "tk"."site_class" (
    "id" uuid NOT NULL,
    "host_key" text NOT NULL,
    "index" bigint NOT NULL,
    "phase" uuid,
    "material" uuid,
    "label" text,
    "ratio_kind" "meta"."site_ratio_kind" NOT NULL,
    "ratio" "meta"."count",
    CONSTRAINT "site_class__pk" PRIMARY KEY ("id"),
    CONSTRAINT "site_class__identity" UNIQUE ("host_key", "index"),
    CONSTRAINT "site_class__ck__one_host" CHECK (num_nonnulls("phase", "material") = 1),
    CONSTRAINT "site_class__ck__index_positive" CHECK ("index" > 0)
);
COMMENT ON TABLE "tk"."site_class" IS 'A sublattice, hydrate cage, surface site type or exchanger: a class of positions that constituents occupy, within a phase definition or on a material.';
COMMENT ON COLUMN "tk"."site_class"."id" IS 'Deterministic identifier of the site_class instance.';
COMMENT ON COLUMN "tk"."site_class"."host_key" IS 'Identifier of the hosting phase definition or material, as text, so the identity is one tuple for both cases.';
COMMENT ON COLUMN "tk"."site_class"."index" IS 'Position of the class within its host, from one.';
COMMENT ON COLUMN "tk"."site_class"."phase" IS 'The hosting phase definition.';
COMMENT ON COLUMN "tk"."site_class"."material" IS 'The hosting material.';
COMMENT ON COLUMN "tk"."site_class"."label" IS 'The class''s name in the source.';
COMMENT ON COLUMN "tk"."site_class"."ratio_kind" IS 'Whether the site ratio is a constant.';
COMMENT ON COLUMN "tk"."site_class"."ratio" IS 'Sites per formula unit, when constant.';

CREATE TABLE "tk"."site_scheme" (
    "id" uuid NOT NULL,
    "key" text NOT NULL,
    CONSTRAINT "site_scheme__pk" PRIMARY KEY ("id"),
    CONSTRAINT "site_scheme__identity" UNIQUE ("key")
);
COMMENT ON TABLE "tk"."site_scheme" IS 'A named way of assigning association sites, such as 2B or 4C. It is part of a parameterisation: the same species under two site schemes is two different sets of parameters.';
COMMENT ON COLUMN "tk"."site_scheme"."id" IS 'Deterministic identifier of the site_scheme instance.';
COMMENT ON COLUMN "tk"."site_scheme"."key" IS 'Stable key of the scheme.';

CREATE TABLE "tk"."slot_uncertainty" (
    "id" uuid NOT NULL,
    "parameter_set" uuid NOT NULL,
    "slot" uuid NOT NULL,
    "index_key" text NOT NULL,
    "kind" "meta"."uncertainty_kind" NOT NULL,
    "magnitude" "meta"."finite_real",
    "relative_magnitude" "meta"."scalar",
    "coverage_factor" "meta"."scalar",
    "confidence_level" "meta"."fraction",
    CONSTRAINT "slot_uncertainty__pk" PRIMARY KEY ("id"),
    CONSTRAINT "slot_uncertainty__identity" UNIQUE ("parameter_set", "slot", "index_key")
);
COMMENT ON TABLE "tk"."slot_uncertainty" IS 'The uncertainty a source states for one slot value. Joint covariance belongs to the fit that produced the values.';
COMMENT ON COLUMN "tk"."slot_uncertainty"."id" IS 'Deterministic identifier of the slot_uncertainty instance.';
COMMENT ON COLUMN "tk"."slot_uncertainty"."parameter_set" IS 'The set.';
COMMENT ON COLUMN "tk"."slot_uncertainty"."slot" IS 'The slot.';
COMMENT ON COLUMN "tk"."slot_uncertainty"."index_key" IS 'Canonical encoding of the family index, empty for a slot outside any family.';
COMMENT ON COLUMN "tk"."slot_uncertainty"."kind" IS 'What the magnitude means.';
COMMENT ON COLUMN "tk"."slot_uncertainty"."magnitude" IS 'The magnitude of a standard, expanded or interval uncertainty, in the slot''s storage unit.';
COMMENT ON COLUMN "tk"."slot_uncertainty"."relative_magnitude" IS 'The magnitude of a relative uncertainty, as a fraction of the value.';
COMMENT ON COLUMN "tk"."slot_uncertainty"."coverage_factor" IS 'Coverage factor of an expanded uncertainty.';
COMMENT ON COLUMN "tk"."slot_uncertainty"."confidence_level" IS 'Level of confidence of an expanded uncertainty.';

CREATE TABLE "prov"."software_release" (
    "id" uuid NOT NULL,
    "version" text NOT NULL,
    "homepage" text,
    CONSTRAINT "software_release__pk" PRIMARY KEY ("id")
);
COMMENT ON TABLE "prov"."software_release" IS 'A released version of a program or library, as the origin of a computation or the reference of a comparison.';
COMMENT ON COLUMN "prov"."software_release"."id" IS 'Deterministic identifier of the software_release instance.';
COMMENT ON COLUMN "prov"."software_release"."version" IS 'The release version.';
COMMENT ON COLUMN "prov"."software_release"."homepage" IS 'Where the release is published.';

CREATE TABLE "prov"."source" (
    "id" uuid NOT NULL,
    "key" text NOT NULL,
    "title" text NOT NULL,
    CONSTRAINT "source__pk" PRIMARY KEY ("id"),
    CONSTRAINT "source__identity" UNIQUE ("key")
);
COMMENT ON TABLE "prov"."source" IS 'An attributable origin of content: a publication, a software release, a database release or an acquired carrier.';
COMMENT ON COLUMN "prov"."source"."id" IS 'Deterministic identifier of the source instance.';
COMMENT ON COLUMN "prov"."source"."key" IS 'Stable key: the manifest id and resolved pin for a carrier; `doi:` and the lower-case DOI for a publication that has one, otherwise `carrier:`, the manifest id of the carrier that cites it, `:` and that carrier''s citation key.';
COMMENT ON COLUMN "prov"."source"."title" IS 'Human-readable title.';

CREATE TABLE "tk"."source_entity" (
    "id" uuid NOT NULL,
    "carrier" uuid NOT NULL,
    "scope" text NOT NULL,
    "local_key" text NOT NULL,
    "entity_class" "meta"."entity_class" NOT NULL,
    "aggregation" uuid,
    "polymorph" text,
    "stated_charge" "meta"."charge_number",
    "status" "meta"."resolution_status" NOT NULL,
    "rule" "meta"."resolution_rule" NOT NULL,
    "target" uuid NOT NULL,
    CONSTRAINT "source_entity__pk" PRIMARY KEY ("id"),
    CONSTRAINT "source_entity__identity" UNIQUE ("carrier", "scope", "local_key"),
    CONSTRAINT "source_entity__ck__local_key_nonempty" CHECK ("local_key" <> '')
);
COMMENT ON TABLE "tk"."source_entity" IS 'The thing a carrier means by one of its keys: a file name, a row name, a registry number used as a key. A source''s records are about source entities until resolution identifies each with a material entity. A provider name is never silently promoted to a canonical identity.';
COMMENT ON COLUMN "tk"."source_entity"."id" IS 'Deterministic identifier of the source_entity instance.';
COMMENT ON COLUMN "tk"."source_entity"."carrier" IS 'The carrier whose key this is.';
COMMENT ON COLUMN "tk"."source_entity"."scope" IS 'The context within the carrier in which the key is unique, such as a table or database file; empty when carrier-wide.';
COMMENT ON COLUMN "tk"."source_entity"."local_key" IS 'The key, verbatim.';
COMMENT ON COLUMN "tk"."source_entity"."entity_class" IS 'The class of thing the source says the key names, as its mapping declares it; it selects the resolution rules.';
COMMENT ON COLUMN "tk"."source_entity"."aggregation" IS 'The state of aggregation the source states for the entity, when its records are about a form rather than a chemical identity.';
COMMENT ON COLUMN "tk"."source_entity"."polymorph" IS 'The polymorph or structure designation the source states.';
COMMENT ON COLUMN "tk"."source_entity"."stated_charge" IS 'The net charge the source states for the entity, where it states one.';
COMMENT ON COLUMN "tk"."source_entity"."status" IS 'Where its resolution stands.';
COMMENT ON COLUMN "tk"."source_entity"."rule" IS 'Which rule decided it.';
COMMENT ON COLUMN "tk"."source_entity"."target" IS 'The entity its records are attached to: the canonical entity when resolved, otherwise a provisional one.';

CREATE TABLE "tk"."speciation_map" (
    "id" uuid NOT NULL,
    "system" uuid NOT NULL,
    "key" text NOT NULL,
    "exactness" "meta"."map_exactness" NOT NULL,
    "invertible" boolean NOT NULL,
    CONSTRAINT "speciation_map__pk" PRIMARY KEY ("id"),
    CONSTRAINT "speciation_map__identity" UNIQUE ("system", "key")
);
COMMENT ON TABLE "tk"."speciation_map" IS 'The relation between an apparent description of a material and its true species within a chemical system. Apparent and true are two descriptions of one material account, never two inventories.';
COMMENT ON COLUMN "tk"."speciation_map"."id" IS 'Deterministic identifier of the speciation_map instance.';
COMMENT ON COLUMN "tk"."speciation_map"."system" IS 'The system.';
COMMENT ON COLUMN "tk"."speciation_map"."key" IS 'Name of the map.';
COMMENT ON COLUMN "tk"."speciation_map"."exactness" IS 'Whether the map is a constant linear map.';
COMMENT ON COLUMN "tk"."speciation_map"."invertible" IS 'Whether the apparent description can be recovered from the true one.';

CREATE TABLE "tk"."species" (
    "id" uuid NOT NULL,
    "charge" "meta"."charge_number" NOT NULL DEFAULT 0.0,
    "inchikey" "meta"."id_inchikey",
    CONSTRAINT "species__pk" PRIMARY KEY ("id"),
    CONSTRAINT "species__uq__inchikey" UNIQUE ("inchikey")
);
COMMENT ON TABLE "tk"."species" IS 'A chemical identity: formula, charge and, where known, structure. A vacancy and the electron are species with an empty formula. Canonical key: the standard InChIKey where one is resolved, otherwise formula, charge and a declared discriminator.';
COMMENT ON COLUMN "tk"."species"."id" IS 'Deterministic identifier of the species instance.';
COMMENT ON COLUMN "tk"."species"."charge" IS 'Net charge number.';
COMMENT ON COLUMN "tk"."species"."inchikey" IS 'The resolved standard InChIKey.';

CREATE TABLE "tk"."species_form" (
    "id" uuid NOT NULL,
    "species" uuid NOT NULL,
    "aggregation" uuid NOT NULL,
    "polymorph" text,
    CONSTRAINT "species_form__pk" PRIMARY KEY ("id"),
    CONSTRAINT "species_form__uq__species_aggregation_polymorph" UNIQUE ("species", "aggregation", "polymorph")
);
COMMENT ON TABLE "tk"."species_form" IS 'A species in a state of aggregation and, for a crystalline solid, a polymorph. This is what thermochemical databases call a species or substance, and what reactions and standard-state data are about. Canonical key: species key, aggregation and polymorph.';
COMMENT ON COLUMN "tk"."species_form"."id" IS 'Deterministic identifier of the species_form instance.';
COMMENT ON COLUMN "tk"."species_form"."species" IS 'The chemical identity.';
COMMENT ON COLUMN "tk"."species_form"."aggregation" IS 'The state of aggregation.';
COMMENT ON COLUMN "tk"."species_form"."polymorph" IS 'Polymorph or structure designation for a crystalline form.';

CREATE TABLE "tk"."standard_state" (
    "id" uuid NOT NULL,
    "key" text NOT NULL,
    "kind" "meta"."standard_state_kind" NOT NULL,
    "scale" uuid,
    "pressure_rule" "meta"."pressure_rule" NOT NULL,
    "pressure" "meta"."pressure",
    "solvent" uuid,
    CONSTRAINT "standard_state__pk" PRIMARY KEY ("id"),
    CONSTRAINT "standard_state__identity" UNIQUE ("key")
);
COMMENT ON TABLE "tk"."standard_state" IS 'The state that defines the standard chemical potential used with an activity or a fugacity.';
COMMENT ON COLUMN "tk"."standard_state"."id" IS 'Deterministic identifier of the standard_state instance.';
COMMENT ON COLUMN "tk"."standard_state"."key" IS 'Stable key.';
COMMENT ON COLUMN "tk"."standard_state"."kind" IS 'The kind of state.';
COMMENT ON COLUMN "tk"."standard_state"."scale" IS 'The composition scale of an infinite-dilution or site reference.';
COMMENT ON COLUMN "tk"."standard_state"."pressure_rule" IS 'How its pressure is fixed.';
COMMENT ON COLUMN "tk"."standard_state"."pressure" IS 'The pressure, when fixed.';
COMMENT ON COLUMN "tk"."standard_state"."solvent" IS 'The solvent of an infinite-dilution reference.';

CREATE TABLE "tk"."tabulated_axis" (
    "id" uuid NOT NULL,
    "function" uuid NOT NULL,
    "ordinal" bigint NOT NULL,
    "axis_type" uuid NOT NULL,
    "points" "meta"."finite_real"[] NOT NULL,
    CONSTRAINT "tabulated_axis__pk" PRIMARY KEY ("id"),
    CONSTRAINT "tabulated_axis__identity" UNIQUE ("function", "ordinal"),
    CONSTRAINT "tabulated_axis__ck__points__no_null" CHECK (array_position("points", NULL) IS NULL)
);
COMMENT ON TABLE "tk"."tabulated_axis" IS 'One axis of a tabulated function.';
COMMENT ON COLUMN "tk"."tabulated_axis"."id" IS 'Deterministic identifier of the tabulated_axis instance.';
COMMENT ON COLUMN "tk"."tabulated_axis"."function" IS 'The function.';
COMMENT ON COLUMN "tk"."tabulated_axis"."ordinal" IS 'Position of the axis, from one.';
COMMENT ON COLUMN "tk"."tabulated_axis"."axis_type" IS 'Quantity type of the axis.';
COMMENT ON COLUMN "tk"."tabulated_axis"."points" IS 'Axis values in the axis type''s storage unit.';

CREATE TABLE "tk"."tabulated_function" (
    "id" uuid NOT NULL,
    "key" text NOT NULL,
    "interpolation" "meta"."interpolation" NOT NULL,
    "distribution" uuid,
    CONSTRAINT "tabulated_function__pk" PRIMARY KEY ("id"),
    CONSTRAINT "tabulated_function__identity" UNIQUE ("key")
);
COMMENT ON TABLE "tk"."tabulated_function" IS 'A function given as values on a grid, with how to evaluate it between points. It has one or more axes and one or more named series on the same grid. Sigma profiles (three series on one axis), collision-integral tables and pore-size kernels (two axes) are tabulated functions.';
COMMENT ON COLUMN "tk"."tabulated_function"."id" IS 'Deterministic identifier of the tabulated_function instance.';
COMMENT ON COLUMN "tk"."tabulated_function"."key" IS 'Stable key, computed from the owning set, slot and index.';
COMMENT ON COLUMN "tk"."tabulated_function"."interpolation" IS 'How it is evaluated between points.';
COMMENT ON COLUMN "tk"."tabulated_function"."distribution" IS 'What the function is a distribution of, when it is one.';

CREATE TABLE "tk"."tabulated_series" (
    "id" uuid NOT NULL,
    "function" uuid NOT NULL,
    "name" text NOT NULL,
    "value_type" uuid NOT NULL,
    "values" "meta"."finite_real"[] NOT NULL,
    CONSTRAINT "tabulated_series__pk" PRIMARY KEY ("id"),
    CONSTRAINT "tabulated_series__identity" UNIQUE ("function", "name"),
    CONSTRAINT "tabulated_series__ck__values__no_null" CHECK (array_position("values", NULL) IS NULL)
);
COMMENT ON TABLE "tk"."tabulated_series" IS 'One named series of values of a tabulated function, over the full grid of its axes.';
COMMENT ON COLUMN "tk"."tabulated_series"."id" IS 'Deterministic identifier of the tabulated_series instance.';
COMMENT ON COLUMN "tk"."tabulated_series"."function" IS 'The function.';
COMMENT ON COLUMN "tk"."tabulated_series"."name" IS 'Name of the series; `value` when the function has one series.';
