COMMENT ON COLUMN "prov"."attribution"."import_record" IS 'The import record.';
COMMENT ON COLUMN "prov"."attribution"."primary" IS 'The source credited with the content.';

CREATE TABLE "tk"."auxiliary_of" (
    "id" uuid NOT NULL,
    "auxiliary" uuid NOT NULL,
    "target" uuid NOT NULL,
    "kind" "meta"."auxiliary_kind" NOT NULL,
    "max_relative_error" "meta"."scalar",
    CONSTRAINT "auxiliary_of__pk" PRIMARY KEY ("auxiliary", "target"),
    CONSTRAINT "auxiliary_of__uq__id" UNIQUE ("id")
);
COMMENT ON TABLE "tk"."auxiliary_of" IS 'A parameter set approximates, inverts or bounds a quantity of another model. It is never an independent authority for that quantity; it carries its accuracy claim and points at what it was derived from.';
