COMMENT ON COLUMN "tk"."auxiliary_of"."auxiliary" IS 'The auxiliary parameter set.';
COMMENT ON COLUMN "tk"."auxiliary_of"."target" IS 'The parameter set, parameterisation or model assembly whose quantity it serves.';
COMMENT ON COLUMN "tk"."auxiliary_of"."kind" IS 'How it relates to the target.';
COMMENT ON COLUMN "tk"."auxiliary_of"."max_relative_error" IS 'The largest relative deviation from the target that the source claims.';

CREATE TABLE "qual"."capability" (
    "id" uuid NOT NULL,
    "library" uuid NOT NULL,
    "calculation" uuid NOT NULL,
    "scope" text NOT NULL,
