COMMENT ON COLUMN "tk"."element_reference"."reference" IS 'The energy reference.';
COMMENT ON COLUMN "tk"."element_reference"."element" IS 'The element.';
COMMENT ON COLUMN "tk"."element_reference"."value" IS 'The value.';

CREATE TABLE "tk"."entity_model" (
    "id" uuid NOT NULL,
    "parameterization" uuid NOT NULL,
    "entity" uuid NOT NULL,
    "value" uuid NOT NULL,
    CONSTRAINT "entity_model__pk" PRIMARY KEY ("parameterization", "entity"),
    CONSTRAINT "entity_model__uq__id" UNIQUE ("id")
);
COMMENT ON TABLE "tk"."entity_model" IS 'The model assembly that describes one entity under a parameterisation, for bodies of data that assemble a model per substance (a standard-state model built from an equation of state, a temperature correction and a pressure correction, with a solvent model).';
COMMENT ON COLUMN "tk"."entity_model"."id" IS 'Deterministic identifier of the row, computed from its keys.';
COMMENT ON COLUMN "tk"."entity_model"."parameterization" IS 'The parameterisation.';
COMMENT ON COLUMN "tk"."entity_model"."entity" IS 'The entity described.';
COMMENT ON COLUMN "tk"."entity_model"."value" IS 'The assembly.';

CREATE TABLE "prov"."equivalence_assessment" (
    "id" uuid NOT NULL,
    "a" uuid NOT NULL,
    "b" uuid NOT NULL,
    "level" "meta"."equivalence_level" NOT NULL,
    "conversion" uuid,
    CONSTRAINT "equivalence_assessment__pk" PRIMARY KEY ("a", "b"),
    CONSTRAINT "equivalence_assessment__uq__id" UNIQUE ("id"),
    CONSTRAINT "equivalence_assessment__ck__canonical" CHECK ("a" <= "b"),
    CONSTRAINT "equivalence_assessment__ck__diagonal" CHECK ("a" <> "b")
);
COMMENT ON TABLE "prov"."equivalence_assessment" IS 'A derived statement that two records assert the same primary fact. It is never an identity and can be rebuilt.';
COMMENT ON COLUMN "prov"."equivalence_assessment"."id" IS 'Deterministic identifier of the row, computed from its keys.';
COMMENT ON COLUMN "prov"."equivalence_assessment"."a" IS 'One record.';
COMMENT ON COLUMN "prov"."equivalence_assessment"."b" IS 'The other record.';
COMMENT ON COLUMN "prov"."equivalence_assessment"."level" IS 'How the two compare.';
COMMENT ON COLUMN "prov"."equivalence_assessment"."conversion" IS 'The conversion under which the two agree, for the level `equal_under_conversion`.';

CREATE TABLE "prov"."fit_correlation" (
    "id" uuid NOT NULL,
    "fit" uuid NOT NULL,
    "a" bigint NOT NULL,
    "b" bigint NOT NULL,
    "coefficient" "meta"."scalar" NOT NULL,
    CONSTRAINT "fit_correlation__pk" PRIMARY KEY ("fit", "a", "b"),
    CONSTRAINT "fit_correlation__uq__id" UNIQUE ("id"),
    CONSTRAINT "fit_correlation__ck__coefficient_in_range" CHECK ("coefficient" >= -1.0 AND "coefficient" <= 1.0),
    CONSTRAINT "fit_correlation__ck__canonical" CHECK ("a" <= "b"),
    CONSTRAINT "fit_correlation__ck__diagonal" CHECK ("a" <> "b")
);
COMMENT ON TABLE "prov"."fit_correlation" IS 'The correlation of the estimates of two free parameters of a fit, which together with their standard uncertainties gives the covariance.';
COMMENT ON COLUMN "prov"."fit_correlation"."id" IS 'Deterministic identifier of the row, computed from its keys.';
COMMENT ON COLUMN "prov"."fit_correlation"."fit" IS 'The fit.';
COMMENT ON COLUMN "prov"."fit_correlation"."a" IS 'Position of one free parameter in the fit''s parameter vector.';
COMMENT ON COLUMN "prov"."fit_correlation"."b" IS 'Position of the other free parameter.';
COMMENT ON COLUMN "prov"."fit_correlation"."coefficient" IS 'The correlation coefficient.';

CREATE TABLE "prov"."fit_free_parameter" (
    "id" uuid NOT NULL,
    "fit" uuid NOT NULL,
    "ordinal" bigint NOT NULL,
    "record" uuid NOT NULL,
    "slot" uuid,
    "standard_uncertainty" "meta"."finite_real",
    "index_key" text NOT NULL DEFAULT '',
    CONSTRAINT "fit_free_parameter__pk" PRIMARY KEY ("fit", "ordinal"),
    CONSTRAINT "fit_free_parameter__uq__id" UNIQUE ("id")
);
COMMENT ON TABLE "prov"."fit_free_parameter" IS 'A parameter a fit was free to vary, addressed down to the coefficient. Uncertainties and correlations are stated over these, by position.';
COMMENT ON COLUMN "prov"."fit_free_parameter"."id" IS 'Deterministic identifier of the row, computed from its keys.';
COMMENT ON COLUMN "prov"."fit_free_parameter"."fit" IS 'The fit.';
COMMENT ON COLUMN "prov"."fit_free_parameter"."ordinal" IS 'Position of the parameter in the fit''s parameter vector, from one.';
COMMENT ON COLUMN "prov"."fit_free_parameter"."record" IS 'The parameter set or entity record the parameter belongs to.';
COMMENT ON COLUMN "prov"."fit_free_parameter"."slot" IS 'The slot, when the record is a parameter set.';
COMMENT ON COLUMN "prov"."fit_free_parameter"."standard_uncertainty" IS 'The standard uncertainty of the fitted value, in the slot''s storage unit.';
COMMENT ON COLUMN "prov"."fit_free_parameter"."index_key" IS 'Canonical encoding of the family index, empty for a slot outside any family.';

