);
COMMENT ON TABLE "qual"."run_parameter_set" IS 'A parameter set a qualification run evaluated.';
COMMENT ON COLUMN "qual"."run_parameter_set"."id" IS 'Deterministic identifier of the row, computed from its keys.';
COMMENT ON COLUMN "qual"."run_parameter_set"."run" IS 'The run.';
COMMENT ON COLUMN "qual"."run_parameter_set"."parameter_set" IS 'A set it evaluated.';

CREATE TABLE "tk"."site_equivalence" (
    "id" uuid NOT NULL,
    "a" uuid NOT NULL,
    "b" uuid NOT NULL,
    CONSTRAINT "site_equivalence__pk" PRIMARY KEY ("a", "b"),
    CONSTRAINT "site_equivalence__uq__id" UNIQUE ("id"),
    CONSTRAINT "site_equivalence__ck__canonical" CHECK ("a" <= "b"),
    CONSTRAINT "site_equivalence__ck__diagonal" CHECK ("a" <> "b")
);
COMMENT ON TABLE "tk"."site_equivalence" IS 'Two site classes that are equivalent under permutation, so parameters are unchanged when their occupants are exchanged.';
COMMENT ON COLUMN "tk"."site_equivalence"."id" IS 'Deterministic identifier of the row, computed from its keys.';
COMMENT ON COLUMN "tk"."site_equivalence"."a" IS 'One site class.';
COMMENT ON COLUMN "tk"."site_equivalence"."b" IS 'An equivalent site class.';

CREATE TABLE "tk"."site_occupant" (
    "id" uuid NOT NULL,
    "site_class" uuid NOT NULL,
    "occupant" uuid NOT NULL,
    CONSTRAINT "site_occupant__pk" PRIMARY KEY ("site_class", "occupant"),
    CONSTRAINT "site_occupant__uq__id" UNIQUE ("id")
);
COMMENT ON TABLE "tk"."site_occupant" IS 'A species that may occupy a site class. A vacancy is a species.';
COMMENT ON COLUMN "tk"."site_occupant"."id" IS 'Deterministic identifier of the row, computed from its keys.';
COMMENT ON COLUMN "tk"."site_occupant"."site_class" IS 'The site class.';
COMMENT ON COLUMN "tk"."site_occupant"."occupant" IS 'An admissible occupant.';

CREATE TABLE "tk"."snapshot_selection" (
    "id" uuid NOT NULL,
    "snapshot" uuid NOT NULL,
    "parameter_set" uuid NOT NULL,
    CONSTRAINT "snapshot_selection__pk" PRIMARY KEY ("snapshot", "parameter_set"),
    CONSTRAINT "snapshot_selection__uq__id" UNIQUE ("id")
);
COMMENT ON TABLE "tk"."snapshot_selection" IS 'A parameter set a snapshot selected.';
COMMENT ON COLUMN "tk"."snapshot_selection"."id" IS 'Deterministic identifier of the row, computed from its keys.';
COMMENT ON COLUMN "tk"."snapshot_selection"."snapshot" IS 'The snapshot.';
COMMENT ON COLUMN "tk"."snapshot_selection"."parameter_set" IS 'A selected set.';

CREATE TABLE "tk"."speciation_coefficient" (
    "id" uuid NOT NULL,
    "map" uuid NOT NULL,
    "apparent" uuid NOT NULL,
    "true_form" uuid NOT NULL,
    "value" "meta"."count" NOT NULL,
    CONSTRAINT "speciation_coefficient__pk" PRIMARY KEY ("map", "apparent", "true_form"),
    CONSTRAINT "speciation_coefficient__uq__id" UNIQUE ("id")
);
COMMENT ON TABLE "tk"."speciation_coefficient" IS 'How much of a true species one unit of an apparent entity contributes, for an exact linear map.';
COMMENT ON COLUMN "tk"."speciation_coefficient"."id" IS 'Deterministic identifier of the row, computed from its keys.';
COMMENT ON COLUMN "tk"."speciation_coefficient"."map" IS 'The map.';
COMMENT ON COLUMN "tk"."speciation_coefficient"."apparent" IS 'The apparent entity.';
COMMENT ON COLUMN "tk"."speciation_coefficient"."true_form" IS 'A true species form.';
COMMENT ON COLUMN "tk"."speciation_coefficient"."value" IS 'The value.';

CREATE TABLE "tk"."subject_subform_choice" (
    "id" uuid NOT NULL,
    "parameterization" uuid NOT NULL,
    "slot" uuid NOT NULL,
    "subject_key" text NOT NULL,
    "ordinal" bigint NOT NULL,
    "form" uuid NOT NULL,
    "source_parameterization" uuid,
    CONSTRAINT "subject_subform_choice__pk" PRIMARY KEY ("parameterization", "slot", "subject_key", "ordinal"),
    CONSTRAINT "subject_subform_choice__uq__id" UNIQUE ("id"),
    CONSTRAINT "subject_subform_choice__ck__ordinal_from_one" CHECK ("ordinal" > 0)
);
COMMENT ON TABLE "tk"."subject_subform_choice" IS 'Which form fills a sub-form slot for one subject under a parameterisation: the form chosen for each pair, component or phase when a model puts a different form in the slot for each. A slot with multiplicity many has several choices, numbered from one.';
COMMENT ON COLUMN "tk"."subject_subform_choice"."id" IS 'Deterministic identifier of the row, computed from its keys.';
COMMENT ON COLUMN "tk"."subject_subform_choice"."parameterization" IS 'The parameterisation the choice is made in.';
COMMENT ON COLUMN "tk"."subject_subform_choice"."slot" IS 'The sub-form slot.';
COMMENT ON COLUMN "tk"."subject_subform_choice"."subject_key" IS 'Canonical encoding of the subjects the choice is for, in the role order of the contract the slot accepts, as for a parameter set.';
COMMENT ON COLUMN "tk"."subject_subform_choice"."ordinal" IS 'Position among the choices of a slot with multiplicity many, from one; one otherwise.';
COMMENT ON COLUMN "tk"."subject_subform_choice"."form" IS 'The form chosen.';
COMMENT ON COLUMN "tk"."subject_subform_choice"."source_parameterization" IS 'The parameterisation that holds the chosen form''s parameter sets, when it is not the one the choice is made in.';

CREATE TABLE "tk"."supersedes" (
    "id" uuid NOT NULL,
    "newer" uuid NOT NULL,
    "older" uuid NOT NULL,
    CONSTRAINT "supersedes__pk" PRIMARY KEY ("newer", "older"),
    CONSTRAINT "supersedes__uq__id" UNIQUE ("id")
);
COMMENT ON TABLE "tk"."supersedes" IS 'A later parameterisation replaces an earlier one; the earlier one remains.';
COMMENT ON COLUMN "tk"."supersedes"."id" IS 'Deterministic identifier of the row, computed from its keys.';
COMMENT ON COLUMN "tk"."supersedes"."newer" IS 'The replacing parameterisation.';
COMMENT ON COLUMN "tk"."supersedes"."older" IS 'The replaced parameterisation.';

CREATE TABLE "tk"."system_conserves" (
    "id" uuid NOT NULL,
    "system" uuid NOT NULL,
    "quantity" uuid NOT NULL,
    CONSTRAINT "system_conserves__pk" PRIMARY KEY ("system", "quantity"),
    CONSTRAINT "system_conserves__uq__id" UNIQUE ("id")
);
COMMENT ON TABLE "tk"."system_conserves" IS 'A conserved quantity a chemical system declares. Every reaction of the system conserves each of them.';
COMMENT ON COLUMN "tk"."system_conserves"."id" IS 'Deterministic identifier of the row, computed from its keys.';
COMMENT ON COLUMN "tk"."system_conserves"."system" IS 'The system.';
COMMENT ON COLUMN "tk"."system_conserves"."quantity" IS 'A conserved quantity.';

CREATE TABLE "tk"."system_member" (
    "id" uuid NOT NULL,
    "system" uuid NOT NULL,
    "form" uuid NOT NULL,
    "role" "meta"."system_role" NOT NULL,
    "member_role" uuid,
    CONSTRAINT "system_member__pk" PRIMARY KEY ("system", "form"),
    CONSTRAINT "system_member__uq__id" UNIQUE ("id")
);
COMMENT ON TABLE "tk"."system_member" IS 'A species form that belongs to a chemical system, with its role there.';
COMMENT ON COLUMN "tk"."system_member"."id" IS 'Deterministic identifier of the row, computed from its keys.';
COMMENT ON COLUMN "tk"."system_member"."system" IS 'The system.';
COMMENT ON COLUMN "tk"."system_member"."form" IS 'A member.';
COMMENT ON COLUMN "tk"."system_member"."role" IS 'Its role in this system.';
COMMENT ON COLUMN "tk"."system_member"."member_role" IS 'The part it plays in the phases of this system, where the source states one.';

CREATE TABLE "tk"."system_reaction" (
    "id" uuid NOT NULL,
    "system" uuid NOT NULL,
    "reaction" uuid NOT NULL,
    "defines" uuid,
    CONSTRAINT "system_reaction__pk" PRIMARY KEY ("system", "reaction"),
    CONSTRAINT "system_reaction__uq__id" UNIQUE ("id")
);
COMMENT ON TABLE "tk"."system_reaction" IS 'A reaction that belongs to a chemical system.';
COMMENT ON COLUMN "tk"."system_reaction"."id" IS 'Deterministic identifier of the row, computed from its keys.';
COMMENT ON COLUMN "tk"."system_reaction"."system" IS 'The system.';
COMMENT ON COLUMN "tk"."system_reaction"."reaction" IS 'A reaction of the system.';
COMMENT ON COLUMN "tk"."system_reaction"."defines" IS 'The secondary species form this reaction defines from the basis, when it is a defining reaction.';

CREATE TABLE "param"."nasa7__pure__piece" (
    "set_id" uuid NOT NULL,
    "n" bigint NOT NULL,
    "T_low" "meta"."temperature" NOT NULL,
    "T_high" "meta"."temperature" NOT NULL,
    "a1" "meta"."scalar" NOT NULL,
    "a2" "meta"."finite_real" NOT NULL,
    "a3" "meta"."finite_real" NOT NULL,
    "a4" "meta"."finite_real" NOT NULL,
    "a5" "meta"."finite_real" NOT NULL,
    "a6" "meta"."temperature_difference" NOT NULL,
    "a7" "meta"."scalar" NOT NULL,
    "interval" "meta"."float8range" GENERATED ALWAYS AS ("meta"."float8range"("T_low", "T_high", '[)')) STORED,
    CONSTRAINT "nasa7__pure__piece__ck__n__minimum" CHECK ("n" >= 1),
    CONSTRAINT "nasa7__pure__piece__pk" PRIMARY KEY ("set_id", "n"),
    CONSTRAINT "nasa7__pure__piece__ck__interval" CHECK ("T_low" < "T_high"),
    CONSTRAINT "nasa7__pure__piece__xc__interval" EXCLUDE USING gist ("set_id" WITH =, "interval" WITH &&)
);
COMMENT ON TABLE "param"."nasa7__pure__piece" IS 'One coefficient block per temperature interval.';
COMMENT ON COLUMN "param"."nasa7__pure__piece"."set_id" IS 'The parameter set this row belongs to.';
COMMENT ON COLUMN "param"."nasa7__pure__piece"."n" IS 'Piece number, ascending in temperature.';
COMMENT ON COLUMN "param"."nasa7__pure__piece"."T_low" IS 'Lower bound of the interval.';
COMMENT ON COLUMN "param"."nasa7__pure__piece"."T_high" IS 'Upper bound of the interval.';
COMMENT ON COLUMN "param"."nasa7__pure__piece"."a1" IS 'Coefficient of T^0 in Cp/R.';
COMMENT ON COLUMN "param"."nasa7__pure__piece"."a2" IS 'Coefficient of T^1 in Cp/R.';
COMMENT ON COLUMN "param"."nasa7__pure__piece"."a3" IS 'Coefficient of T^2 in Cp/R.';
COMMENT ON COLUMN "param"."nasa7__pure__piece"."a4" IS 'Coefficient of T^3 in Cp/R.';
COMMENT ON COLUMN "param"."nasa7__pure__piece"."a5" IS 'Coefficient of T^4 in Cp/R.';
COMMENT ON COLUMN "param"."nasa7__pure__piece"."a6" IS 'Enthalpy integration constant: H/R at the zero of the polynomial integral.';
COMMENT ON COLUMN "param"."nasa7__pure__piece"."a7" IS 'Entropy integration constant: S/R at the zero of the polynomial integral.';
COMMENT ON COLUMN "param"."nasa7__pure__piece"."interval" IS 'The half-open interval [lower, upper) the piece covers.';

CREATE TABLE "param"."nasa9__pure__piece" (
    "set_id" uuid NOT NULL,
