    CONSTRAINT "nasa9__pure__piece__pk" PRIMARY KEY ("set_id", "n"),
    CONSTRAINT "nasa9__pure__piece__ck__interval" CHECK ("T_low" < "T_high"),
    CONSTRAINT "nasa9__pure__piece__xc__interval" EXCLUDE USING gist ("set_id" WITH =, "interval" WITH &&)
);
COMMENT ON TABLE "param"."nasa9__pure__piece" IS 'One coefficient block per temperature interval.';
COMMENT ON COLUMN "param"."nasa9__pure__piece"."set_id" IS 'The parameter set this row belongs to.';
COMMENT ON COLUMN "param"."nasa9__pure__piece"."n" IS 'Piece number, ascending in temperature.';
COMMENT ON COLUMN "param"."nasa9__pure__piece"."T_low" IS 'Lower bound of the interval.';
COMMENT ON COLUMN "param"."nasa9__pure__piece"."T_high" IS 'Upper bound of the interval.';
COMMENT ON COLUMN "param"."nasa9__pure__piece"."a1" IS 'Coefficient of T^-2 in Cp/R.';
COMMENT ON COLUMN "param"."nasa9__pure__piece"."a2" IS 'Coefficient of T^-1 in Cp/R.';
COMMENT ON COLUMN "param"."nasa9__pure__piece"."a3" IS 'Coefficient of T^0 in Cp/R.';
COMMENT ON COLUMN "param"."nasa9__pure__piece"."a4" IS 'Coefficient of T^1 in Cp/R.';
COMMENT ON COLUMN "param"."nasa9__pure__piece"."a5" IS 'Coefficient of T^2 in Cp/R.';
COMMENT ON COLUMN "param"."nasa9__pure__piece"."a6" IS 'Coefficient of T^3 in Cp/R.';
COMMENT ON COLUMN "param"."nasa9__pure__piece"."a7" IS 'Coefficient of T^4 in Cp/R.';
COMMENT ON COLUMN "param"."nasa9__pure__piece"."b1" IS 'Enthalpy integration constant over R.';
COMMENT ON COLUMN "param"."nasa9__pure__piece"."b2" IS 'Entropy integration constant over R.';
COMMENT ON COLUMN "param"."nasa9__pure__piece"."interval" IS 'The half-open interval [lower, upper) the piece covers.';

CREATE TABLE "param"."shomate__pure__piece" (
    "set_id" uuid NOT NULL,
    "n" bigint NOT NULL,
    "T_low" "meta"."temperature" NOT NULL,
    "T_high" "meta"."temperature" NOT NULL,
    "A" "meta"."molar_entropy" NOT NULL,
    "B" "meta"."finite_real" NOT NULL,
    "C" "meta"."finite_real" NOT NULL,
    "D" "meta"."finite_real" NOT NULL,
    "E" "meta"."finite_real" NOT NULL,
    "F" "meta"."molar_energy" NOT NULL,
    "G" "meta"."molar_entropy" NOT NULL,
    "interval" "meta"."float8range" GENERATED ALWAYS AS ("meta"."float8range"("T_low", "T_high", '[)')) STORED,
    CONSTRAINT "shomate__pure__piece__ck__n__minimum" CHECK ("n" >= 1),
    CONSTRAINT "shomate__pure__piece__pk" PRIMARY KEY ("set_id", "n"),
    CONSTRAINT "shomate__pure__piece__ck__interval" CHECK ("T_low" < "T_high"),
    CONSTRAINT "shomate__pure__piece__xc__interval" EXCLUDE USING gist ("set_id" WITH =, "interval" WITH &&)
);
COMMENT ON TABLE "param"."shomate__pure__piece" IS 'One coefficient block per temperature interval.';
COMMENT ON COLUMN "param"."shomate__pure__piece"."set_id" IS 'The parameter set this row belongs to.';
COMMENT ON COLUMN "param"."shomate__pure__piece"."n" IS 'Piece number, ascending in temperature.';
COMMENT ON COLUMN "param"."shomate__pure__piece"."T_low" IS 'Lower bound of the interval.';
COMMENT ON COLUMN "param"."shomate__pure__piece"."T_high" IS 'Upper bound of the interval.';
COMMENT ON COLUMN "param"."shomate__pure__piece"."A" IS 'Constant term of the heat capacity.';
COMMENT ON COLUMN "param"."shomate__pure__piece"."B" IS 'Coefficient of T in the heat capacity.';
COMMENT ON COLUMN "param"."shomate__pure__piece"."C" IS 'Coefficient of T^2 in the heat capacity.';
COMMENT ON COLUMN "param"."shomate__pure__piece"."D" IS 'Coefficient of T^3 in the heat capacity.';
COMMENT ON COLUMN "param"."shomate__pure__piece"."E" IS 'Coefficient of T^-2 in the heat capacity.';
COMMENT ON COLUMN "param"."shomate__pure__piece"."F" IS 'Enthalpy constant.';
COMMENT ON COLUMN "param"."shomate__pure__piece"."G" IS 'Entropy constant.';
COMMENT ON COLUMN "param"."shomate__pure__piece"."interval" IS 'The half-open interval [lower, upper) the piece covers.';

